// Inhalte für „Ist das halal?“ auf koshertrivia.de/halal
// Antworten aus sunnitischer Sicht; wo die Gelehrten sich uneinig sind, lautet die Antwort „kommt drauf an“.
// Quellen: Quran mit Tafsir Ibn Kathir, Sahih al-Bukhari (Nummerierung nach Fath al-Bari) und Sahih Muslim (Nummerierung nach Abd al-Baqi).
window.HALAL = [
  {"cat": "Essen", "q": "Schweinefleisch essen", "a": "haram", "e": "Der Quran verbietet Schweinefleisch ausdrücklich. Ibn Kathir erklärt, dass damit das ganze Schwein gemeint ist – auch Fett und alle anderen Teile.", "src": "Quran 2:173 mit Tafsir Ibn Kathir", "lv": 1},
  {"cat": "Essen", "q": "Schweinefleisch essen, wenn du sonst verhungern würdest", "a": "halal", "e": "In echter Not ist es erlaubt – aber nur so viel, wie man zum Überleben braucht. Ibn Kathir betont, dass man es weder will noch über das Nötige hinausgeht.", "src": "Quran 2:173 mit Tafsir Ibn Kathir", "lv": 2},
  {"cat": "Essen", "q": "Gummibärchen mit Schweinegelatine essen", "a": "kommt", "e": "Die meisten Gelehrten und Fatwa-Räte sagen: haram, weil die Gelatine aus dem Schwein stammt. Einige hanafitische Gelehrte meinen, sie sei durch die Verarbeitung so verändert, dass sie erlaubt ist. Auf der sicheren Seite bist du mit Halal- oder veganen Fruchtgummis.", "src": "Quran 2:173 mit Tafsir Ibn Kathir", "lv": 3},
  {"cat": "Essen", "q": "Bier trinken", "a": "haram", "e": "Alkohol (khamr) ist im Quran verboten. Der Prophet ﷺ sagte: Jedes Rauschmittel ist khamr, und jedes khamr ist haram.", "src": "Quran 5:90–91 mit Tafsir Ibn Kathir · Sahih Muslim 2003", "lv": 1},
  {"cat": "Essen", "q": "Einen kleinen Schluck Wein trinken", "a": "haram", "e": "Verboten ist das berauschende Getränk selbst, nicht erst der Rausch. Deshalb ist auch ein kleiner Schluck nicht erlaubt.", "src": "Quran 5:90 mit Tafsir Ibn Kathir · Sahih al-Bukhari 242 · Sahih Muslim 2003", "lv": 2},
  {"cat": "Essen", "q": "Alkoholfreies Bier (0,0 %) trinken", "a": "kommt", "e": "Entscheidend ist, ob ein Getränk berauscht. Manche Gelehrte erlauben 0,0-Bier deshalb, andere raten ab, weil es Bier nachahmt und Spuren von Alkohol enthalten kann.", "src": "Sahih al-Bukhari 242 · Sahih Muslim 2003", "lv": 3},
  {"cat": "Essen", "q": "Kiffen", "a": "haram", "e": "Umar sagte in einer Predigt: Khamr ist alles, was den Verstand benebelt. Cannabis berauscht – damit fällt es unter das Verbot.", "src": "Quran 5:90 mit Tafsir Ibn Kathir · Sahih al-Bukhari 5581 · Sahih Muslim 2003", "lv": 1},
  {"cat": "Essen", "q": "Lachgas aus Ballons einatmen", "a": "haram", "e": "Lachgas berauscht und kann Nerven und Gehirn schwer schädigen. Der Quran sagt: Tötet euch nicht selbst – Ibn Kathir erklärt, dass man sich nicht durch Verbotenes ins Verderben stürzen soll.", "src": "Quran 4:29 mit Tafsir Ibn Kathir · Sahih Muslim 2003", "lv": 2},
  {"cat": "Essen", "q": "Vapen mit Nikotin", "a": "haram", "e": "Die meisten heutigen Gelehrten und Fatwa-Räte sagen: haram, weil es süchtig macht und der Gesundheit schadet. Sie stützen sich auf den Vers, sich nicht ins Verderben zu stürzen, und darauf, dass Schädliches (khaba'ith) verboten ist. Einige ältere Meinungen stuften Rauchen nur als makruh ein.", "src": "Quran 2:195 mit Tafsir Ibn Kathir · Quran 7:157 mit Tafsir Ibn Kathir", "lv": 2},
  {"cat": "Essen", "q": "Vapen ohne Nikotin", "a": "kommt", "e": "Ohne Nikotin fällt die Sucht weg, aber Schäden für die Lunge sind weiter möglich. Manche Gelehrte halten es deshalb für haram, andere für makruh.", "src": "Quran 2:195 mit Tafsir Ibn Kathir", "lv": 3},
  {"cat": "Essen", "q": "Shisha rauchen", "a": "haram", "e": "Für Shisha gilt dasselbe wie für Zigaretten: Die meisten heutigen Gelehrten sagen haram, weil sie der Gesundheit schadet – eine Shisha-Session kann so viel Rauch bedeuten wie viele Zigaretten.", "src": "Quran 2:195 mit Tafsir Ibn Kathir · Quran 7:157 mit Tafsir Ibn Kathir", "lv": 2},
  {"cat": "Essen", "q": "Energy-Drinks trinken", "a": "halal", "e": "Energy-Drinks berauschen nicht. Grundsätzlich ist alles erlaubt, was nicht verboten ist. In großen Mengen sind sie aber ungesund.", "src": "Quran 2:168 mit Tafsir Ibn Kathir", "lv": 2},
  {"cat": "Essen", "q": "Kaffee trinken", "a": "halal", "e": "Kaffee berauscht nicht. Ibn Kathir erklärt zu 2:29, dass Allah alles auf der Erde zum Nutzen der Menschen geschaffen hat – erlaubt ist, was nicht verboten wurde.", "src": "Quran 2:29 mit Tafsir Ibn Kathir", "lv": 1},
  {"cat": "Essen", "q": "Fisch essen", "a": "halal", "e": "Der Quran erlaubt, was aus dem Meer kommt. Die Gefährten aßen sogar von einem großen Fisch (al-'Anbar), den das Meer tot angespült hatte.", "src": "Quran 5:96 mit Tafsir Ibn Kathir · Sahih al-Bukhari 4362 · Sahih Muslim 1935", "lv": 1},
  {"cat": "Essen", "q": "Garnelen essen", "a": "kommt", "e": "Für Malikiten, Schafiiten und Hanbaliten sind alle Meerestiere halal. In der hanafitischen Schule ist nur Fisch erlaubt – ob Garnelen als Fisch zählen, sehen hanafitische Gelehrte unterschiedlich.", "src": "Quran 5:96 mit Tafsir Ibn Kathir", "lv": 3},
  {"cat": "Essen", "q": "Heuschrecken essen", "a": "halal", "e": "Die Gefährten aßen mit dem Propheten ﷺ Heuschrecken – und zwar auf sieben Feldzügen.", "src": "Sahih al-Bukhari 5495 · Sahih Muslim 1952", "lv": 3},
  {"cat": "Essen", "q": "Fleisch vom Hausesel essen", "a": "haram", "e": "Am Tag von Khaybar verbot der Prophet ﷺ das Fleisch von Hauseseln.", "src": "Sahih al-Bukhari 5520 · Sahih Muslim 1941", "lv": 2},
  {"cat": "Essen", "q": "Pferdefleisch essen", "a": "kommt", "e": "Laut Jabir erlaubte der Prophet ﷺ Pferdefleisch – die meisten Gelehrten halten es deshalb für halal. Abu Hanifa hielt es für makruh.", "src": "Sahih al-Bukhari 5520 · Sahih Muslim 1941", "lv": 3},
  {"cat": "Essen", "q": "Fleisch von Löwe oder Wolf essen", "a": "haram", "e": "Der Prophet ﷺ verbot, Raubtiere mit Reißzähnen zu essen.", "src": "Sahih al-Bukhari 5530 · Sahih Muslim 1932", "lv": 2},
  {"cat": "Essen", "q": "Blutwurst essen", "a": "haram", "e": "Blut ist im Quran ausdrücklich verboten, genau wie verendete Tiere und Schweinefleisch.", "src": "Quran 5:3 mit Tafsir Ibn Kathir", "lv": 2},
  {"cat": "Essen", "q": "Mit der linken Hand essen", "a": "makruh", "e": "Der Prophet ﷺ sagte: Esst mit der rechten Hand, denn der Satan isst mit der linken. Die meisten Gelehrten halten das Essen mit links für makruh – wer die rechte nicht benutzen kann, darf natürlich links essen.", "src": "Sahih Muslim 2020", "lv": 2},
  {"cat": "Essen", "q": "Aus einem Becher aus Gold trinken", "a": "haram", "e": "Gefäße aus Gold und Silber sind zum Essen und Trinken verboten – für Männer und Frauen.", "src": "Sahih al-Bukhari 5426 · Sahih Muslim 2067", "lv": 3},
  {"cat": "Essen", "q": "Über Essen meckern", "a": "makruh", "e": "Der Prophet ﷺ hat nie Essen schlechtgemacht: Wenn es ihm schmeckte, aß er es, sonst ließ er es stehen.", "src": "Sahih al-Bukhari 5409 · Sahih Muslim 2064", "lv": 3},
  {"cat": "Essen", "q": "Essen einfach wegwerfen", "a": "haram", "e": "Verschwendung (israf) ist verboten: Esst und trinkt, aber verschwendet nicht. Ibn Kathir erklärt zu 17:27, dass Verschwender Brüder der Satane genannt werden.", "src": "Quran 7:31 mit Tafsir Ibn Kathir · Quran 17:26–27 mit Tafsir Ibn Kathir", "lv": 2},
  {"cat": "Essen", "q": "Veganes Essen von nicht-muslimischen Nachbarn essen", "a": "halal", "e": "Pflanzliches Essen ist erlaubt, egal wer es kocht – solange kein Alkohol oder anderes Verbotenes drin ist. Bei Fleisch gelten eigene Regeln.", "src": "Quran 2:172 mit Tafsir Ibn Kathir", "lv": 3},
  {"cat": "Essen", "q": "Weiteressen, nachdem du gemerkt hast, dass Schwein drin ist", "a": "haram", "e": "Was du aus Versehen gegessen hast, ist keine Sünde – Allah zieht niemanden für Vergessen oder Irrtum zur Rechenschaft. Sobald du es weißt, musst du aber aufhören.", "src": "Quran 2:173 mit Tafsir Ibn Kathir · Quran 2:286 mit Tafsir Ibn Kathir", "lv": 2},
  {"cat": "Essen", "q": "Honig essen", "a": "halal", "e": "Der Quran nennt Honig eine Heilung für die Menschen. Ibn Kathir erklärt, dass er für viele Beschwerden nützlich ist.", "src": "Quran 16:69 mit Tafsir Ibn Kathir", "lv": 1},
  {"cat": "Essen", "q": "Hustensaft mit etwas Alkohol nehmen", "a": "kommt", "e": "Der Prophet ﷺ sagte über Wein: Er ist keine Medizin, sondern eine Krankheit. Viele heutige Gelehrte erlauben aber Medikamente, in denen Alkohol nur als Lösungsmittel in kleiner, nicht berauschender Menge steckt – vor allem, wenn es keine Alternative gibt.", "src": "Sahih Muslim 1984", "lv": 3},
  {"cat": "Essen", "q": "Viel Knoblauch essen und direkt in die Moschee gehen", "a": "makruh", "e": "Der Prophet ﷺ sagte: Wer Knoblauch oder Zwiebeln gegessen hat, soll unserer Moschee fernbleiben – wegen des Geruchs, der andere stört.", "src": "Sahih al-Bukhari 855 · Sahih Muslim 564", "lv": 3},
  {"cat": "Essen", "q": "Wasser trinken im Stehen", "a": "kommt", "e": "Es gibt Überlieferungen, in denen der Prophet ﷺ das Trinken im Stehen untersagt, und andere, in denen er selbst stehend trank. Viele Gelehrte sagen deshalb: erlaubt, aber im Sitzen ist besser.", "src": "Sahih al-Bukhari 5615 · Sahih Muslim 2024", "lv": 3},
  {"cat": "Geld", "q": "Zinsen auf dem Sparkonto kassieren", "a": "haram", "e": "Zinsen (riba) sind im Quran verboten. Allah hat den Handel erlaubt und die Zinsen verboten – Ibn Kathir zählt riba zu den schwersten Vergehen.", "src": "Quran 2:275 mit Tafsir Ibn Kathir · Quran 2:278–279 mit Tafsir Ibn Kathir · Sahih Muslim 1598", "lv": 1},
  {"cat": "Geld", "q": "Kredit mit Zinsen für ein neues Handy", "a": "haram", "e": "Der Prophet ﷺ verfluchte den, der Zinsen nimmt, und den, der sie bezahlt – ebenso den, der den Vertrag schreibt, und die Zeugen.", "src": "Quran 2:275 mit Tafsir Ibn Kathir · Sahih Muslim 1598", "lv": 2},
  {"cat": "Geld", "q": "Einen Kredit aufnehmen", "a": "kommt", "e": "Ein Kredit ohne Zinsen ist halal – der Quran regelt sogar, wie man Schulden aufschreibt. Sobald Zinsen anfallen, wird er haram.", "src": "Quran 2:282 mit Tafsir Ibn Kathir · Quran 2:275 mit Tafsir Ibn Kathir · Sahih Muslim 1598", "lv": 3},
  {"cat": "Geld", "q": "Schulden absichtlich nicht zurückzahlen", "a": "haram", "e": "Der Prophet ﷺ sagte: Wenn ein Reicher das Zurückzahlen hinauszögert, ist das Unrecht. Und: Wer Geld nimmt und es zurückzahlen will, dem hilft Allah dabei.", "src": "Sahih al-Bukhari 2287, 2387 · Sahih Muslim 1564", "lv": 1},
  {"cat": "Geld", "q": "Im Casino spielen", "a": "haram", "e": "Glücksspiel (maysir) ist im Quran zusammen mit Alkohol verboten. Ibn Kathir erklärt maysir als Glücksspiel (qimar).", "src": "Quran 5:90–91 mit Tafsir Ibn Kathir", "lv": 1},
  {"cat": "Geld", "q": "Sportwetten abschließen", "a": "haram", "e": "Bei Wetten setzt du Geld ein, und einer gewinnt, was der andere verliert – das ist Glücksspiel (maysir). Der Quran sagt, dass sein Schaden größer ist als sein Nutzen.", "src": "Quran 2:219 mit Tafsir Ibn Kathir · Quran 5:90 mit Tafsir Ibn Kathir", "lv": 1},
  {"cat": "Geld", "q": "Wette unter Freunden: Wer verliert, zahlt den Döner", "a": "haram", "e": "Auch kleine Einsätze machen eine Wette zu Glücksspiel, wenn der Verlierer für den Gewinner zahlt.", "src": "Quran 5:90 mit Tafsir Ibn Kathir", "lv": 2},
  {"cat": "Geld", "q": "Kostenloses Gewinnspiel ohne Einsatz", "a": "halal", "e": "Glücksspiel bedeutet: Du setzt etwas ein und kannst es verlieren. Bei einem kostenlosen Gewinnspiel verlierst du nichts – deshalb ist es kein maysir.", "src": "Quran 5:90 mit Tafsir Ibn Kathir", "lv": 2},
  {"cat": "Geld", "q": "Lootboxen mit echtem Geld kaufen", "a": "kommt", "e": "Du zahlst und weißt nicht, was du bekommst – viele Gelehrte sehen darin Glücksspiel und raten klar ab. Kostenlose Lootboxen ohne Einsatz sind unproblematisch.", "src": "Quran 5:90 mit Tafsir Ibn Kathir · Sahih Muslim 1513", "lv": 3},
  {"cat": "Geld", "q": "Aktien kaufen", "a": "kommt", "e": "Handel ist erlaubt. Halal sind Aktien, wenn die Firma etwas Erlaubtes macht und ihr Geschäft nicht auf Zinsen, Alkohol oder Glücksspiel beruht.", "src": "Quran 2:275 mit Tafsir Ibn Kathir", "lv": 3},
  {"cat": "Geld", "q": "Sneaker günstig kaufen und teurer weiterverkaufen", "a": "halal", "e": "Handel mit Gewinn ist erlaubt: Allah hat den Handel erlaubt. Wichtig ist nur, dass du ehrlich bist und nichts über die Ware verschweigst.", "src": "Quran 2:275 mit Tafsir Ibn Kathir · Sahih al-Bukhari 2072", "lv": 2},
  {"cat": "Geld", "q": "Beim Verkauf verschweigen, dass das Handy einen Riss hat", "a": "haram", "e": "Der Prophet ﷺ fand bei einem Händler nasses Getreide unter trockenem und sagte: Wer betrügt, gehört nicht zu mir.", "src": "Sahih Muslim 102", "lv": 1},
  {"cat": "Geld", "q": "Jemanden bestechen", "a": "haram", "e": "Der Quran verbietet, Besitz zu Unrecht zu verschlingen und damit Richter oder Amtsträger zu bestechen.", "src": "Quran 2:188 mit Tafsir Ibn Kathir", "lv": 1},
  {"cat": "Geld", "q": "Schwarzfahren", "a": "haram", "e": "Wer ohne Ticket fährt, nimmt eine Leistung, ohne zu bezahlen – das ist Besitz zu Unrecht verschlingen.", "src": "Quran 2:188 mit Tafsir Ibn Kathir · Quran 5:1 mit Tafsir Ibn Kathir", "lv": 1},
  {"cat": "Geld", "q": "Etwas im Laden mitgehen lassen", "a": "haram", "e": "Diebstahl ist eine schwere Sünde. Der Prophet ﷺ sagte sogar über den, der ein Ei stiehlt: Allah verflucht den Dieb.", "src": "Quran 5:38 mit Tafsir Ibn Kathir · Sahih al-Bukhari 6783 · Sahih Muslim 1687", "lv": 1},
  {"cat": "Geld", "q": "Gefundenes Portemonnaie einfach behalten", "a": "haram", "e": "Fundsachen muss man bekannt machen, damit der Besitzer sie zurückbekommt. Einfach behalten ist nicht erlaubt.", "src": "Sahih al-Bukhari 2372 · Sahih Muslim 1722", "lv": 1},
  {"cat": "Geld", "q": "Einem Mitarbeiter den Lohn nicht zahlen", "a": "haram", "e": "Allah sagt in einem Hadith Qudsi: Ich bin am Tag der Auferstehung der Gegner dessen, der einen Arbeiter einstellt und ihm seinen Lohn nicht gibt.", "src": "Sahih al-Bukhari 2227", "lv": 1},
  {"cat": "Geld", "q": "Mit eigener Arbeit Geld verdienen", "a": "halal", "e": "Der Prophet ﷺ sagte: Niemand isst besseres Essen als das, was er mit seiner eigenen Hände Arbeit verdient.", "src": "Sahih al-Bukhari 2072", "lv": 1},
  {"cat": "Geld", "q": "Betteln, obwohl man gar nicht in Not ist", "a": "haram", "e": "Der Prophet ﷺ warnte: Wer ständig bettelt, kommt am Tag der Auferstehung ohne Fleisch im Gesicht.", "src": "Sahih al-Bukhari 1474 · Sahih Muslim 1040", "lv": 2},
  {"cat": "Geld", "q": "An Bedürftige spenden", "a": "halal", "e": "Der Quran vergleicht eine Spende mit einem Korn, aus dem sieben Ähren wachsen, mit hundert Körnern in jeder Ähre.", "src": "Quran 2:261 mit Tafsir Ibn Kathir", "lv": 1},
  {"cat": "Geld", "q": "Zakat nicht zahlen, obwohl man muss", "a": "haram", "e": "Zakat ist eine Säule des Islam. Der Prophet ﷺ warnte: Wer sie nicht zahlt, dessen Besitz wird am Tag der Auferstehung zu einer giftigen Schlange.", "src": "Quran 9:34–35 mit Tafsir Ibn Kathir · Sahih al-Bukhari 1403", "lv": 2},
  {"cat": "Gebet & Fasten", "q": "Ein Pflichtgebet absichtlich auslassen", "a": "haram", "e": "Der Prophet ﷺ sagte: Zwischen dem Menschen und dem Unglauben steht das Unterlassen des Gebets.", "src": "Quran 19:59 mit Tafsir Ibn Kathir · Sahih Muslim 82", "lv": 1},
  {"cat": "Gebet & Fasten", "q": "In Schuhen beten", "a": "halal", "e": "Anas wurde gefragt, ob der Prophet ﷺ in seinen Sandalen betete – er sagte ja. Die Schuhe müssen sauber sein.", "src": "Sahih al-Bukhari 386 · Sahih Muslim 555", "lv": 3},
  {"cat": "Gebet & Fasten", "q": "Nach dem Asr-Gebet noch freiwillig beten", "a": "makruh", "e": "Der Prophet ﷺ untersagte freiwillige Gebete nach Asr bis zum Sonnenuntergang. Nachgeholte Pflichtgebete sind davon nicht betroffen.", "src": "Sahih al-Bukhari 586 · Sahih Muslim 827", "lv": 3},
  {"cat": "Gebet & Fasten", "q": "Direkt vor jemandem vorbeilaufen, der betet", "a": "haram", "e": "Der Prophet ﷺ sagte: Wüsste der Vorbeigehende, was er auf sich lädt, würde er lieber vierzig warten.", "src": "Sahih al-Bukhari 510 · Sahih Muslim 507", "lv": 3},
  {"cat": "Gebet & Fasten", "q": "In der Moschee schlafen", "a": "halal", "e": "Ibn Umar schlief als junger, unverheirateter Mann in der Moschee des Propheten ﷺ.", "src": "Sahih al-Bukhari 440", "lv": 2},
  {"cat": "Gebet & Fasten", "q": "In der Moschee auf den Boden spucken", "a": "haram", "e": "Der Prophet ﷺ sagte: Spucken in der Moschee ist eine Sünde.", "src": "Sahih al-Bukhari 415 · Sahih Muslim 552", "lv": 2},
  {"cat": "Gebet & Fasten", "q": "Freitagsgebet ohne Grund schwänzen (für Männer)", "a": "haram", "e": "Der Quran ruft zum Freitagsgebet. Der Prophet ﷺ warnte, dass Allah das Herz derer versiegelt, die es vernachlässigen.", "src": "Quran 62:9 mit Tafsir Ibn Kathir · Sahih Muslim 865", "lv": 2},
  {"cat": "Gebet & Fasten", "q": "Quran ohne Wudu auswendig aufsagen", "a": "halal", "e": "Aischa berichtete, dass der Prophet ﷺ Allahs zu jeder Zeit gedachte. Auswendig rezitieren geht auch ohne Wudu.", "src": "Sahih Muslim 373", "lv": 3},
  {"cat": "Gebet & Fasten", "q": "Den Quran ohne Wudu anfassen", "a": "kommt", "e": "Die meisten Gelehrten verlangen Wudu, um den Mushaf zu berühren, und stützen sich unter anderem auf 56:79. Andere verstehen den Vers als Aussage über die Engel und erlauben es.", "src": "Quran 56:79 mit Tafsir Ibn Kathir", "lv": 3},
  {"cat": "Gebet & Fasten", "q": "Dua auf Deutsch machen", "a": "halal", "e": "Allah sagt: Ich bin nahe und erhöre den Bittenden. Du kannst in jeder Sprache zu Allah beten.", "src": "Quran 2:186 mit Tafsir Ibn Kathir", "lv": 2},
  {"cat": "Gebet & Fasten", "q": "Ruqya mit der Fatiha machen", "a": "halal", "e": "Ein Gefährte las die Fatiha über einen Kranken, und der Prophet ﷺ bestätigte das.", "src": "Sahih al-Bukhari 5736 · Sahih Muslim 2201", "lv": 3},
  {"cat": "Gebet & Fasten", "q": "Auf der Toilette in Richtung Qibla – in einem Gebäude", "a": "kommt", "e": "Im Freien hat der Prophet ﷺ es untersagt. Ibn Umar sah ihn aber in einem Haus anders sitzen. Viele Gelehrte erlauben es deshalb in Gebäuden, andere meiden es überall.", "src": "Sahih al-Bukhari 144, 148 · Sahih Muslim 264", "lv": 3},
  {"cat": "Gebet & Fasten", "q": "Im Stehen urinieren", "a": "halal", "e": "Hudhayfa berichtete, dass der Prophet ﷺ an einem Abfallplatz im Stehen urinierte. Wichtig ist, dass man sich nicht beschmutzt.", "src": "Sahih al-Bukhari 224 · Sahih Muslim 273", "lv": 2},
  {"cat": "Gebet & Fasten", "q": "Beim Wudu mit Wasser verschwenden", "a": "makruh", "e": "Der Prophet ﷺ machte Wudu mit sehr wenig Wasser (einem mudd). Verschwendung ist auch beim Wudu nicht gut.", "src": "Quran 7:31 mit Tafsir Ibn Kathir · Sahih al-Bukhari 201", "lv": 3},
  {"cat": "Gebet & Fasten", "q": "Am Tag des Eid fasten", "a": "haram", "e": "Der Prophet ﷺ hat das Fasten an den beiden Eid-Tagen verboten.", "src": "Sahih al-Bukhari 1990 · Sahih Muslim 1137", "lv": 2},
  {"cat": "Gebet & Fasten", "q": "Nur am Freitag fasten", "a": "makruh", "e": "Der Prophet ﷺ sagte: Fastet nicht nur am Freitag, außer mit einem Tag davor oder danach.", "src": "Sahih al-Bukhari 1985 · Sahih Muslim 1144", "lv": 3},
  {"cat": "Gebet & Fasten", "q": "Im Ramadan aus Versehen trinken – und dann weiterfasten", "a": "halal", "e": "Wer aus Vergessen isst oder trinkt, soll sein Fasten vollenden – Allah hat ihm zu essen und zu trinken gegeben.", "src": "Sahih al-Bukhari 1933 · Sahih Muslim 1155", "lv": 2},
  {"cat": "Gebet & Fasten", "q": "Als Kranker im Ramadan nicht fasten", "a": "halal", "e": "Wer krank ist, darf das Fasten aussetzen und die Tage später nachholen.", "src": "Quran 2:184–185 mit Tafsir Ibn Kathir", "lv": 1},
  {"cat": "Gebet & Fasten", "q": "Auf Reisen das Fasten brechen", "a": "halal", "e": "Der Quran erlaubt Reisenden, später nachzuholen. Der Prophet ﷺ sagte zu Hamza al-Aslami: Faste, wenn du willst, oder brich das Fasten, wenn du willst.", "src": "Quran 2:184 mit Tafsir Ibn Kathir · Sahih al-Bukhari 1943 · Sahih Muslim 1121", "lv": 2},
  {"cat": "Gebet & Fasten", "q": "Fasten während der Periode", "a": "haram", "e": "Während der Periode wird nicht gefastet und nicht gebetet. Die Fastentage werden später nachgeholt, die Gebete nicht.", "src": "Sahih al-Bukhari 304 · Sahih Muslim 335", "lv": 2},
  {"cat": "Gebet & Fasten", "q": "Duschen, während man fastet", "a": "halal", "e": "Der Prophet ﷺ wachte manchmal im Ramadan im Zustand der großen Unreinheit auf, wusch sich und fastete.", "src": "Sahih al-Bukhari 1926 · Sahih Muslim 1109", "lv": 3},
  {"cat": "Miteinander", "q": "Die Eltern anschreien", "a": "haram", "e": "Der Quran sagt: Sag zu ihnen nicht einmal „uff“ und fahr sie nicht an. Ibn Kathir erklärt, dass schon das kleinste abfällige Wort verboten ist.", "src": "Quran 17:23 mit Tafsir Ibn Kathir", "lv": 1},
  {"cat": "Miteinander", "q": "Den Eltern nicht gehorchen, wenn sie eine Sünde verlangen", "a": "halal", "e": "Gehorsam gibt es nur im Guten. Der Quran sagt: Wenn sie dich zu etwas Falschem drängen, gehorche ihnen nicht – aber begleite sie weiter freundlich.", "src": "Quran 31:15 mit Tafsir Ibn Kathir · Sahih al-Bukhari 7257 · Sahih Muslim 1840", "lv": 2},
  {"cat": "Miteinander", "q": "Kontakt zur nicht-muslimischen Mutter halten", "a": "halal", "e": "Asma fragte den Propheten ﷺ, ob sie ihrer nicht-muslimischen Mutter Gutes tun darf. Er sagte: Ja, halte die Beziehung zu deiner Mutter.", "src": "Quran 60:8 mit Tafsir Ibn Kathir · Sahih al-Bukhari 2620 · Sahih Muslim 1003", "lv": 2},
  {"cat": "Miteinander", "q": "Den Kontakt zu Verwandten abbrechen", "a": "haram", "e": "Der Prophet ﷺ sagte: Wer die Verwandtschaftsbande zerreißt, kommt nicht ins Paradies.", "src": "Sahih al-Bukhari 5984 · Sahih Muslim 2556", "lv": 1},
  {"cat": "Miteinander", "q": "Nach einem Streit länger als drei Tage nicht reden", "a": "haram", "e": "Der Prophet ﷺ sagte: Es ist nicht erlaubt, seinen Bruder länger als drei Nächte zu meiden. Der Bessere ist, wer zuerst grüßt.", "src": "Sahih al-Bukhari 6077 · Sahih Muslim 2560", "lv": 2},
  {"cat": "Miteinander", "q": "Lästern", "a": "haram", "e": "Lästern (ghiba) heißt, über jemanden etwas zu sagen, das er nicht hören möchte. Der Quran vergleicht es damit, das Fleisch seines toten Bruders zu essen.", "src": "Quran 49:12 mit Tafsir Ibn Kathir · Sahih Muslim 2589", "lv": 1},
  {"cat": "Miteinander", "q": "Gerüchte weitertragen", "a": "haram", "e": "Der Prophet ﷺ sagte: Wer Gerede weiterträgt, um Streit zu säen, kommt nicht ins Paradies.", "src": "Sahih al-Bukhari 6056 · Sahih Muslim 105", "lv": 1},
  {"cat": "Miteinander", "q": "Nachrichten teilen, ohne zu prüfen, ob sie stimmen", "a": "haram", "e": "Der Quran sagt: Wenn euch jemand eine Nachricht bringt, prüft sie, damit ihr nicht anderen aus Unwissenheit schadet.", "src": "Quran 49:6 mit Tafsir Ibn Kathir", "lv": 2},
  {"cat": "Miteinander", "q": "Lügen, um zwei zerstrittene Freunde zu versöhnen", "a": "halal", "e": "Der Prophet ﷺ sagte: Wer Menschen versöhnt und dabei Gutes sagt, ist kein Lügner.", "src": "Sahih al-Bukhari 2692 · Sahih Muslim 2605", "lv": 3},
  {"cat": "Miteinander", "q": "Lügen", "a": "haram", "e": "Der Prophet ﷺ sagte: Die Wahrheit führt zum Guten und das Gute ins Paradies. Die Lüge führt zum Schlechten und das Schlechte ins Feuer.", "src": "Quran 9:119 mit Tafsir Ibn Kathir · Sahih al-Bukhari 6094 · Sahih Muslim 2607", "lv": 1},
  {"cat": "Miteinander", "q": "Ein Versprechen brechen", "a": "haram", "e": "Der Prophet ﷺ nannte es ein Zeichen des Heuchlers: Wenn er etwas verspricht, hält er es nicht.", "src": "Quran 17:34 mit Tafsir Ibn Kathir · Sahih al-Bukhari 33 · Sahih Muslim 59", "lv": 1},
  {"cat": "Miteinander", "q": "Jemanden wegen seines Aussehens auslachen", "a": "haram", "e": "Der Quran sagt: Keiner soll über den anderen spotten – vielleicht ist der andere besser als er.", "src": "Quran 49:11 mit Tafsir Ibn Kathir", "lv": 1},
  {"cat": "Miteinander", "q": "Jemandem neidisch wünschen, dass er verliert, was er hat", "a": "haram", "e": "Der Prophet ﷺ sagte: Beneidet einander nicht, hasst einander nicht und seid Brüder.", "src": "Sahih al-Bukhari 6065", "lv": 2},
  {"cat": "Miteinander", "q": "Jemanden bewundern und genauso gut werden wollen", "a": "halal", "e": "Das ist gesunder Ehrgeiz (ghibta). Der Prophet ﷺ sagte: Beneiden darf man nur zwei – den, der sein Geld im Guten ausgibt, und den, der Wissen hat und es lehrt.", "src": "Sahih al-Bukhari 73 · Sahih Muslim 816", "lv": 3},
  {"cat": "Miteinander", "q": "Einen Muslim beschimpfen", "a": "haram", "e": "Der Prophet ﷺ sagte: Einen Muslim zu beschimpfen ist Frevel (fusuq).", "src": "Sahih al-Bukhari 48 · Sahih Muslim 64", "lv": 1},
  {"cat": "Miteinander", "q": "Jemanden verfluchen", "a": "haram", "e": "Der Prophet ﷺ sagte: Einen Gläubigen zu verfluchen ist wie ihn zu töten.", "src": "Sahih al-Bukhari 6047", "lv": 2},
  {"cat": "Miteinander", "q": "Heimlich das Handy eines Freundes durchsuchen", "a": "haram", "e": "Der Quran sagt: Spioniert einander nicht nach.", "src": "Quran 49:12 mit Tafsir Ibn Kathir", "lv": 2},
  {"cat": "Miteinander", "q": "Im Spaß ein Messer auf jemanden richten", "a": "haram", "e": "Der Prophet ﷺ sagte: Keiner soll mit einer Waffe auf seinen Bruder zeigen – der Satan könnte seine Hand führen.", "src": "Sahih al-Bukhari 7072 · Sahih Muslim 2617", "lv": 2},
  {"cat": "Miteinander", "q": "Die Nachbarn ständig nerven", "a": "haram", "e": "Der Prophet ﷺ sagte: Der ist kein Gläubiger, vor dessen Bosheit sein Nachbar nicht sicher ist.", "src": "Sahih al-Bukhari 6016 · Sahih Muslim 46", "lv": 1},
  {"cat": "Miteinander", "q": "Eine heimliche Beziehung vor der Ehe", "a": "haram", "e": "Der Quran sagt: Kommt der Unzucht nicht nahe. Ibn Kathir erklärt, dass auch alles verboten ist, was dorthin führt.", "src": "Quran 17:32 mit Tafsir Ibn Kathir · Quran 24:30 mit Tafsir Ibn Kathir", "lv": 1},
  {"cat": "Miteinander", "q": "Pornos schauen", "a": "haram", "e": "Der Quran fordert Männer und Frauen auf, ihre Blicke zu senken und ihre Scham zu bewahren.", "src": "Quran 24:30–31 mit Tafsir Ibn Kathir", "lv": 1},
  {"cat": "Miteinander", "q": "Witze über den Islam machen", "a": "haram", "e": "Der Quran tadelt die, die über Allah, Seine Zeichen und Seinen Gesandten spotten und dann sagen, sie hätten nur gescherzt.", "src": "Quran 9:65–66 mit Tafsir Ibn Kathir", "lv": 2},
  {"cat": "Miteinander", "q": "„Ich schwöre auf meine Mutter“ sagen", "a": "haram", "e": "Der Prophet ﷺ sagte: Allah verbietet euch, bei euren Vätern zu schwören. Wer schwört, schwöre bei Allah oder schweige.", "src": "Sahih al-Bukhari 6646 · Sahih Muslim 1646", "lv": 3},
  {"cat": "Miteinander", "q": "„Wallah“ aus Gewohnheit sagen", "a": "kommt", "e": "Gedankenlose Schwüre wie „nein, wallah“ werden nicht angerechnet – so erklärte Aischa den Vers 5:89. Wer aber bewusst bei Allah schwört, muss es ernst meinen.", "src": "Quran 5:89 mit Tafsir Ibn Kathir · Sahih al-Bukhari 4613", "lv": 3},
  {"cat": "Miteinander", "q": "Mit „Wallah“ bewusst lügen", "a": "haram", "e": "Ein falscher Schwur bei Allah (al-yamin al-ghamus) zählt zu den großen Sünden.", "src": "Quran 3:77 mit Tafsir Ibn Kathir · Sahih al-Bukhari 6675", "lv": 2},
  {"cat": "Miteinander", "q": "Weinen, wenn jemand stirbt", "a": "halal", "e": "Als sein Sohn Ibrahim starb, weinte der Prophet ﷺ und sagte: Das Auge weint und das Herz ist traurig.", "src": "Sahih al-Bukhari 1303 · Sahih Muslim 2315", "lv": 2},
  {"cat": "Miteinander", "q": "Bei einer Beerdigung schreien und sich ins Gesicht schlagen", "a": "haram", "e": "Der Prophet ﷺ sagte: Nicht zu uns gehört, wer sich auf die Wangen schlägt und seine Kleidung zerreißt.", "src": "Sahih al-Bukhari 1294 · Sahih Muslim 103", "lv": 2},
  {"cat": "Körper", "q": "Sich ein Tattoo stechen lassen", "a": "haram", "e": "Der Prophet ﷺ verfluchte die, die tätowieren und sich tätowieren lassen.", "src": "Sahih al-Bukhari 5931 · Sahih Muslim 2125", "lv": 1},
  {"cat": "Körper", "q": "Augenbrauen zupfen", "a": "haram", "e": "Im selben Hadith wie das Tattoo-Verbot wird das Auszupfen der Augenbrauen genannt. Die meisten Gelehrten verstehen es als verboten.", "src": "Sahih al-Bukhari 5931 · Sahih Muslim 2125", "lv": 3},
  {"cat": "Körper", "q": "Haarverlängerung (Extensions) tragen", "a": "haram", "e": "Der Prophet ﷺ verfluchte die, die fremdes Haar an das eigene ansetzen und ansetzen lassen.", "src": "Sahih al-Bukhari 5934 · Sahih Muslim 2122", "lv": 3},
  {"cat": "Körper", "q": "Als Mann eine Goldkette tragen", "a": "haram", "e": "Der Prophet ﷺ verbot Männern Goldschmuck. Als er einen Mann mit Goldring sah, nahm er ihn ab und warf ihn weg.", "src": "Sahih al-Bukhari 5863 · Sahih Muslim 2090", "lv": 2},
  {"cat": "Körper", "q": "Als Frau Goldschmuck tragen", "a": "halal", "e": "Frauen dürfen Gold tragen – darüber sind sich die Gelehrten einig. Am Eid spendeten Frauen sogar ihren Schmuck.", "src": "Quran 43:18 mit Tafsir Ibn Kathir · Sahih al-Bukhari 98", "lv": 2},
  {"cat": "Körper", "q": "Als Mann einen Silberring tragen", "a": "halal", "e": "Der Prophet ﷺ trug selbst einen Silberring, in den „Muhammad Rasulullah“ eingraviert war.", "src": "Sahih al-Bukhari 65", "lv": 3},
  {"cat": "Körper", "q": "Als Mann ein Seidenhemd tragen", "a": "haram", "e": "Der Prophet ﷺ sagte: Wer im Diesseits Seide trägt, trägt sie nicht im Jenseits. Das gilt für Männer.", "src": "Sahih al-Bukhari 5832 · Sahih Muslim 2069", "lv": 3},
  {"cat": "Körper", "q": "Als Frau ein Seidenkleid tragen", "a": "halal", "e": "Der Prophet ﷺ schenkte Ali ein Seidengewand und sagte, er solle es unter den Frauen seiner Familie aufteilen.", "src": "Sahih al-Bukhari 2614 · Sahih Muslim 2071", "lv": 2},
  {"cat": "Körper", "q": "Graue Haare färben – nicht schwarz", "a": "halal", "e": "Der Prophet ﷺ sagte: Juden und Christen färben nicht, also unterscheidet euch von ihnen. Viele Gelehrte empfehlen Henna.", "src": "Sahih al-Bukhari 3462 · Sahih Muslim 2103", "lv": 3},
  {"cat": "Körper", "q": "Haare teilweise rasieren, teilweise lang lassen", "a": "makruh", "e": "Der Prophet ﷺ untersagte qaza' – einen Teil des Kopfes zu rasieren und einen anderen stehen zu lassen.", "src": "Sahih al-Bukhari 5921 · Sahih Muslim 2120", "lv": 3},
  {"cat": "Körper", "q": "Fingernägel über 40 Tage nicht schneiden", "a": "makruh", "e": "Anas sagte: Uns wurde eine Frist gesetzt, die Nägel zu schneiden – nicht länger als vierzig Nächte.", "src": "Sahih al-Bukhari 5889 · Sahih Muslim 258", "lv": 3},
  {"cat": "Körper", "q": "Eine Schönheits-OP machen lassen", "a": "kommt", "e": "Aus reiner Eitelkeit gilt sie als Veränderung der Schöpfung Allahs, die im Hadith verflucht wird. Aus medizinischen Gründen oder nach einem Unfall ist sie erlaubt.", "src": "Sahih al-Bukhari 5931 · Sahih Muslim 2125", "lv": 3},
  {"cat": "Körper", "q": "Parfüm mit Alkohol benutzen", "a": "kommt", "e": "Viele heutige Gelehrte erlauben es, weil es nicht getrunken wird und nicht berauscht. Andere halten Alkohol für unrein und raten davon ab.", "src": "Quran 5:90 mit Tafsir Ibn Kathir", "lv": 3},
  {"cat": "Alltag", "q": "Einen Wachhund für Haus und Hof halten", "a": "halal", "e": "Der Prophet ﷺ erlaubte Hunde zum Jagen, für die Herde und für die Landwirtschaft.", "src": "Sahih al-Bukhari 2322 · Sahih Muslim 1575", "lv": 3},
  {"cat": "Alltag", "q": "Einen Hund nur als Haustier in der Wohnung halten", "a": "kommt", "e": "Wer ohne Bedarf einen Hund hält, dem wird laut Hadith täglich Lohn abgezogen. Die meisten Gelehrten halten es für haram, manche für makruh.", "src": "Sahih al-Bukhari 5480 · Sahih Muslim 1574", "lv": 3},
  {"cat": "Alltag", "q": "Einen Vogel als Haustier halten", "a": "halal", "e": "Der kleine Abu Umayr hatte einen Vogel, und der Prophet ﷺ fragte ihn im Spaß: Was hat dein Vögelchen gemacht?", "src": "Sahih al-Bukhari 6129 · Sahih Muslim 2150", "lv": 1},
  {"cat": "Alltag", "q": "Tiere quälen", "a": "haram", "e": "Eine Frau kam ins Feuer, weil sie eine Katze einsperrte, ohne ihr Futter zu geben.", "src": "Sahih al-Bukhari 3318 · Sahih Muslim 2242", "lv": 1},
  {"cat": "Alltag", "q": "Auf lebende Tiere zielen", "a": "haram", "e": "Der Prophet ﷺ sagte: Nehmt nichts, das eine Seele hat, als Zielscheibe.", "src": "Sahih al-Bukhari 5515 · Sahih Muslim 1957", "lv": 2},
  {"cat": "Alltag", "q": "Einen Ameisenhaufen anzünden", "a": "haram", "e": "Ein früherer Prophet ließ einen Ameisenhaufen verbrennen, und Allah tadelte ihn dafür. Strafe mit Feuer steht nur Allah zu.", "src": "Sahih al-Bukhari 3019, 3016 · Sahih Muslim 2241", "lv": 3},
  {"cat": "Alltag", "q": "Einem durstigen Hund Wasser geben", "a": "halal", "e": "Ein Mann gab einem durstigen Hund Wasser, und Allah vergab ihm dafür. Für jedes Lebewesen gibt es Lohn.", "src": "Sahih al-Bukhari 2363 · Sahih Muslim 2244", "lv": 2},
  {"cat": "Alltag", "q": "Zu einem Wahrsager gehen", "a": "haram", "e": "Der Prophet ﷺ sagte: Wer einen Wahrsager aufsucht und ihn etwas fragt, dessen Gebet wird vierzig Nächte nicht angenommen.", "src": "Sahih Muslim 2230", "lv": 2},
  {"cat": "Alltag", "q": "Zauberei (Sihr) betreiben", "a": "haram", "e": "Zauberei gehört zu den sieben verderblichen Sünden.", "src": "Quran 2:102 mit Tafsir Ibn Kathir · Sahih al-Bukhari 2766 · Sahih Muslim 89", "lv": 1},
  {"cat": "Alltag", "q": "Videospiele spielen", "a": "kommt", "e": "Spielen an sich ist erlaubt. Haram wird es, wenn das Spiel verbotene Inhalte hat oder du deswegen Gebete verpasst.", "src": "Quran 62:9 mit Tafsir Ibn Kathir", "lv": 3},
  {"cat": "Alltag", "q": "Kinder mit Puppen spielen lassen", "a": "halal", "e": "Aischa spielte als Mädchen im Haus des Propheten ﷺ mit Puppen, und ihre Freundinnen kamen zum Spielen.", "src": "Sahih al-Bukhari 6130 · Sahih Muslim 2440", "lv": 3},
  {"cat": "Alltag", "q": "Bogenschießen als Sport", "a": "halal", "e": "Der Prophet ﷺ sagte: Die Stärke liegt im Schießen – und wiederholte es dreimal.", "src": "Sahih Muslim 1917", "lv": 2},
  {"cat": "Alltag", "q": "In der Klausur abschreiben", "a": "haram", "e": "Der Prophet ﷺ sagte: Wer betrügt, gehört nicht zu mir. Abschreiben täuscht Lehrer und benachteiligt alle, die ehrlich lernen.", "src": "Sahih Muslim 102", "lv": 1},
  {"cat": "Miteinander", "q": "Auf andere herabschauen, weil sie keine Markenklamotten haben", "a": "haram", "e": "Der Prophet ﷺ sagte: Wer auch nur ein Senfkorn Hochmut im Herzen hat, kommt nicht ins Paradies. Schöne Kleidung ist dabei kein Problem – Hochmut heißt, die Wahrheit abzulehnen und Menschen zu verachten.", "src": "Sahih Muslim 91", "lv": 1, "d": "2026-11-13"},
  {"cat": "Miteinander", "q": "Jemanden mit einem fiesen Spitznamen rufen", "a": "haram", "e": "Der Quran sagt: Gebt einander keine beleidigenden Beinamen. Ein Spitzname, den der andere nicht mag, ist kein harmloser Spaß.", "src": "Quran 49:11 mit Tafsir Ibn Kathir", "lv": 1, "d": "2026-11-13"},
  {"cat": "Miteinander", "q": "Ohne Erlaubnis in die Wohnung eines Freundes gehen", "a": "haram", "e": "Der Quran sagt: Betretet keine fremden Häuser, bevor ihr um Erlaubnis gebeten und gegrüßt habt. Abu Musa bat bei Umar dreimal um Einlass – und ging, als keine Antwort kam.", "src": "Quran 24:27–28 mit Tafsir Ibn Kathir · Sahih al-Bukhari 6245", "lv": 2, "d": "2026-11-13"},
  {"cat": "Essen", "q": "Hasenfleisch essen", "a": "halal", "e": "Anas fing einen Hasen, Abu Talha schlachtete ihn und schickte dem Propheten ﷺ eine Keule – und er nahm sie an.", "src": "Sahih al-Bukhari 5535 · Sahih Muslim 1953", "lv": 2, "d": "2026-11-13"},
  {"cat": "Essen", "q": "Beim Trinken ins Glas atmen", "a": "makruh", "e": "Der Prophet ﷺ sagte: Wenn ihr trinkt, atmet nicht in das Gefäß. Besser: absetzen, ausatmen, weitertrinken.", "src": "Sahih al-Bukhari 5630 · Sahih Muslim 267", "lv": 3, "d": "2026-11-13"},
  {"cat": "Essen", "q": "Einen heruntergefallenen Bissen aufheben und essen", "a": "halal", "e": "Der Prophet ﷺ sagte: Fällt einem ein Bissen herunter, soll er ihn aufheben, den Schmutz entfernen und ihn essen – und ihn nicht dem Satan lassen.", "src": "Sahih Muslim 2033", "lv": 3, "d": "2026-11-13"},
  {"cat": "Miteinander", "q": "Einen kranken Freund besuchen", "a": "halal", "e": "Kranke zu besuchen gehört zu den Rechten, die ein Muslim gegenüber anderen Muslimen hat – zusammen mit dem Erwidern des Grußes und der Annahme einer Einladung.", "src": "Sahih al-Bukhari 1240 · Sahih Muslim 2162", "lv": 1, "d": "2026-11-13"},
  {"cat": "Alltag", "q": "Einem Freund einfach so ein Geschenk machen", "a": "halal", "e": "Aischa berichtete: Der Prophet ﷺ nahm Geschenke an und schenkte selbst etwas zurück.", "src": "Sahih al-Bukhari 2585", "lv": 1, "d": "2026-11-13"},
  {"cat": "Gebet & Fasten", "q": "Im Sitzen beten, weil man nicht stehen kann", "a": "halal", "e": "Der Prophet ﷺ sagte zu einem Kranken: Bete im Stehen; wenn du nicht kannst, im Sitzen; und wenn auch das nicht geht, auf der Seite liegend.", "src": "Sahih al-Bukhari 1117", "lv": 2, "d": "2026-11-13"},
  {"cat": "Gebet & Fasten", "q": "Tayammum statt Wudu, wenn kein Wasser da ist", "a": "halal", "e": "Der Quran erlaubt, sich mit reiner Erde zu reinigen, wenn kein Wasser da ist. Der Prophet ﷺ sagte zu einem Mann ohne Wasser: Mach Tayammum mit Erde, das genügt dir.", "src": "Quran 4:43 mit Tafsir Ibn Kathir · Quran 5:6 mit Tafsir Ibn Kathir · Sahih al-Bukhari 344", "lv": 2, "d": "2026-11-13"},
  {"cat": "Miteinander", "q": "Einen peinlichen Fehler eines Mitschülers in der Klassengruppe verbreiten", "a": "haram", "e": "Der Prophet ﷺ sagte: Wer die Fehler eines Muslims bedeckt, dessen Fehler bedeckt Allah am Tag der Auferstehung. Peinliches über andere herumzuschicken ist das genaue Gegenteil davon.", "src": "Sahih al-Bukhari 2442 · Sahih Muslim 2580", "lv": 1, "d": "2026-11-14"},
  {"cat": "Miteinander", "q": "Zu zweit tuscheln, während ein dritter Freund danebensteht", "a": "haram", "e": "Der Prophet ﷺ sagte: Wenn ihr zu dritt seid, sollen nicht zwei miteinander flüstern und den dritten ausschließen – denn das macht ihn traurig.", "src": "Sahih al-Bukhari 6290 · Sahih Muslim 2184", "lv": 2, "d": "2026-11-14"},
  {"cat": "Miteinander", "q": "Auf Social Media damit prahlen, was man Verbotenes gemacht hat", "a": "haram", "e": "Der Prophet ﷺ sagte: Allen aus meiner Gemeinschaft wird vergeben, außer denen, die ihre Sünden öffentlich machen – wer nachts etwas tut, das Allah verborgen hat, und es am Morgen herumerzählt.", "src": "Sahih al-Bukhari 6069 · Sahih Muslim 2990", "lv": 2, "d": "2026-11-14"},
  {"cat": "Essen", "q": "Essen, ohne vorher „Bismillah“ zu sagen", "a": "makruh", "e": "Der Prophet ﷺ sagte zu einem Jungen: Nenne den Namen Allahs, iss mit der rechten Hand und iss von dem, was vor dir liegt. Die meisten Gelehrten halten das Bismillah für Sunna – es wegzulassen ist deshalb makruh.", "src": "Sahih al-Bukhari 5376 · Sahih Muslim 2022", "lv": 3, "d": "2026-11-14"},
  {"cat": "Essen", "q": "Fleisch vom muslimischen Metzger essen, ohne zu wissen, ob beim Schlachten Bismillah gesagt wurde", "a": "halal", "e": "Leute fragten den Propheten ﷺ nach Fleisch, bei dem sie nicht wussten, ob Allahs Name genannt wurde. Er sagte: Nennt ihr Allahs Namen darüber und esst.", "src": "Sahih al-Bukhari 5507", "lv": 3, "d": "2026-11-14"},
  {"cat": "Essen", "q": "Eine Wüstenechse (Dabb) essen", "a": "halal", "e": "Dem Propheten ﷺ wurde gebratene Echse serviert. Er aß selbst nicht davon, weil er sie nicht kannte – Khalid ibn al-Walid aß sie aber vor ihm, und er sagte: Sie ist nicht verboten.", "src": "Sahih al-Bukhari 5537 · Sahih Muslim 1945", "lv": 3, "d": "2026-11-14"},
  {"cat": "Alltag", "q": "Beim Gähnen den Mund weit offen lassen", "a": "makruh", "e": "Der Prophet ﷺ sagte: Gähnen kommt vom Satan – wer gähnen muss, soll es so gut es geht unterdrücken und die Hand vor den Mund halten.", "src": "Sahih al-Bukhari 6223 · Sahih Muslim 2995", "lv": 3, "d": "2026-11-14"},
  {"cat": "Alltag", "q": "Eine Glasscherbe vom Gehweg räumen", "a": "halal", "e": "Der Prophet ﷺ erzählte von einem Mann, der einen Dornenzweig vom Weg räumte – Allah war mit ihm zufrieden und vergab ihm. Hindernisse wegzuräumen ist eine gute Tat.", "src": "Sahih al-Bukhari 652 · Sahih Muslim 1914", "lv": 1, "d": "2026-11-14"},
  {"cat": "Gebet & Fasten", "q": "Zum Gemeinschaftsgebet rennen, weil es schon angefangen hat", "a": "makruh", "e": "Der Prophet ﷺ sagte: Wenn ihr die Iqama hört, geht ruhig und gelassen zum Gebet und eilt nicht. Betet, was ihr noch erreicht, und holt den Rest nach.", "src": "Sahih al-Bukhari 636 · Sahih Muslim 602", "lv": 3, "d": "2026-11-14"},
  {"cat": "Gebet & Fasten", "q": "Im Ramadan vor der Morgendämmerung Suhur essen", "a": "halal", "e": "Der Prophet ﷺ sagte: Esst Suhur, denn darin liegt Segen. Es ist Sunna, vor dem Fasten noch etwas zu essen.", "src": "Sahih al-Bukhari 1923 · Sahih Muslim 1095", "lv": 2, "d": "2026-11-14"},
  {"cat": "Miteinander", "q": "Auch Leute grüßen, die man nicht kennt", "a": "halal", "e": "Ein Mann fragte den Propheten ﷺ, was im Islam gut ist. Er antwortete: Essen ausgeben und den Salam-Gruß sagen – zu denen, die du kennst, und zu denen, die du nicht kennst.", "src": "Sahih al-Bukhari 12 · Sahih Muslim 39", "lv": 1, "d": "2026-11-15"},
  {"cat": "Miteinander", "q": "Im Klassenchat lieber nichts schreiben, statt etwas Gemeines zu posten", "a": "halal", "e": "Der Prophet ﷺ sagte: Wer an Allah und den Jüngsten Tag glaubt, soll Gutes sagen oder schweigen. Das gilt auch für alles, was man online schreibt.", "src": "Sahih al-Bukhari 6018 · Sahih Muslim 47", "lv": 2, "d": "2026-11-15"},
  {"cat": "Miteinander", "q": "Einem Mitschüler beistehen, der gemobbt wird", "a": "halal", "e": "Der Prophet ﷺ sagte: Hilf deinem Bruder, ob er Unrecht tut oder ihm Unrecht getan wird. Dem Opfer hilft man, indem man ihm beisteht – dem Täter, indem man ihn davon abhält.", "src": "Sahih al-Bukhari 2444 · Sahih Muslim 2584", "lv": 1, "d": "2026-11-15"},
  {"cat": "Essen", "q": "Nach dem Essen die Finger ablecken", "a": "halal", "e": "Der Prophet ﷺ sagte: Wenn ihr esst, wischt eure Hand nicht ab, bevor ihr sie abgeleckt habt. Er sagte auch: Ihr wisst nicht, in welchem Teil des Essens der Segen liegt.", "src": "Sahih al-Bukhari 5456 · Sahih Muslim 2031, 2033", "lv": 2, "d": "2026-11-15"},
  {"cat": "Essen", "q": "Sein Essen mit einem Gast teilen, obwohl es nur knapp reicht", "a": "halal", "e": "Der Prophet ﷺ sagte: Das Essen von zweien reicht für drei, und das Essen von dreien reicht für vier. Teilen bringt Segen.", "src": "Sahih al-Bukhari 5392 · Sahih Muslim 2058", "lv": 1, "d": "2026-11-15"},
  {"cat": "Essen", "q": "Fleisch von einem Adler oder Falken essen", "a": "kommt", "e": "Der Prophet ﷺ verbot, Raubtiere mit Reißzähnen und Vögel mit Krallen zu essen. Die meisten Gelehrten (Hanafiten, Schafiiten, Hanbaliten) halten Greifvögel deshalb für haram, die Malikiten sehen sie dagegen meist nur als makruh an.", "src": "Sahih Muslim 1934", "lv": 3, "d": "2026-11-15"},
  {"cat": "Alltag", "q": "Nach dem Niesen „Alhamdulillah“ sagen", "a": "halal", "e": "Der Prophet ﷺ sagte: Wer niest, soll „Alhamdulillah“ sagen, und wer es hört, antwortet „Yarhamuk Allah“ – Allah erbarme sich deiner.", "src": "Sahih al-Bukhari 6224 · Sahih Muslim 2991", "lv": 1, "d": "2026-11-15"},
  {"cat": "Alltag", "q": "Beim Anziehen der Schuhe mit dem rechten Fuß anfangen", "a": "halal", "e": "Der Prophet ﷺ sagte: Zieht beim Anziehen zuerst den rechten Schuh an und beim Ausziehen zuerst den linken. Eine kleine Sunna für jeden Tag.", "src": "Sahih al-Bukhari 5855 · Sahih Muslim 2097", "lv": 3, "d": "2026-11-15"},
  {"cat": "Gebet & Fasten", "q": "Am Tag von Arafa freiwillig fasten, wenn man nicht auf Pilgerfahrt ist", "a": "halal", "e": "Der Prophet ﷺ sagte, er hoffe bei Allah, dass das Fasten am Tag von Arafa die Sünden des vergangenen und des kommenden Jahres sühnt. Es ist eine stark empfohlene Sunna.", "src": "Sahih Muslim 1162", "lv": 3, "d": "2026-11-15"},
  {"cat": "Gebet & Fasten", "q": "Auf einer Reise die Vier-Rak'a-Gebete auf zwei Rak'as kürzen", "a": "halal", "e": "Der Quran erlaubt, das Gebet auf Reisen zu kürzen. Anas berichtet, dass der Prophet ﷺ auf der Reise von Medina nach Mekka die Gebete mit zwei Rak'as betete, bis er zurück in Medina war.", "src": "Quran 4:101 mit Tafsir Ibn Kathir · Sahih al-Bukhari 1081 · Sahih Muslim 693", "lv": 2, "d": "2026-11-15"},
  {"cat": "Miteinander", "q": "Nicht zurückgrüßen, wenn ein Mitschüler dich mit „Salam“ grüßt", "a": "haram", "e": "Der Quran sagt: Wenn ihr gegrüßt werdet, dann grüßt mit einem noch schöneren Gruß zurück oder erwidert ihn. Einen Gruß zu erwidern ist deshalb Pflicht, nicht nur eine nette Geste.", "src": "Quran 4:86 mit Tafsir Ibn Kathir", "lv": 2, "d": "2026-11-16"},
  {"cat": "Alltag", "q": "Bei einer Gruppenarbeit nichts beitragen, aber sich für das Ergebnis loben lassen", "a": "haram", "e": "Der Quran tadelt Menschen, die gern für etwas gelobt werden, das sie gar nicht getan haben. Wer sich mit der Arbeit anderer schmückt, täuscht Lehrer und Mitschüler.", "src": "Quran 3:188 mit Tafsir Ibn Kathir", "lv": 3, "d": "2026-11-16"},
  {"cat": "Miteinander", "q": "Beim Fußball vor Wut einen Gegenspieler schlagen", "a": "haram", "e": "Der Quran lobt die, die ihren Zorn zurückhalten. Der Prophet ﷺ sagte: Stark ist nicht, wer andere niederringt, sondern wer sich beherrscht, wenn er wütend ist.", "src": "Quran 3:134 mit Tafsir Ibn Kathir · Sahih al-Bukhari 6114 · Sahih Muslim 2609", "lv": 1, "d": "2026-11-16"},
  {"cat": "Essen", "q": "Fleisch von einem Huhn essen, das erwürgt wurde", "a": "haram", "e": "Der Quran zählt erwürgte Tiere ausdrücklich zu dem, was verboten ist – genau wie verendete Tiere und Blut. Ein Tier muss richtig geschlachtet werden.", "src": "Quran 5:3 mit Tafsir Ibn Kathir", "lv": 2, "d": "2026-11-16"},
  {"cat": "Essen", "q": "Ein Wildtier essen, das ein Muslim mit seinem abgerichteten Jagdhund erlegt hat", "a": "halal", "e": "Der Quran erlaubt, was abgerichtete Jagdtiere für einen fangen, wenn man Allahs Namen darüber nennt. Der Prophet ﷺ sagte zu Adi ibn Hatim: Wenn du deinen abgerichteten Hund mit Bismillah losschickst, darfst du die Beute essen – auch wenn der Hund sie getötet hat.", "src": "Quran 5:4 mit Tafsir Ibn Kathir · Sahih al-Bukhari 5476 · Sahih Muslim 1929", "lv": 3, "d": "2026-11-16"},
  {"cat": "Essen", "q": "Frische Datteln zusammen mit Gurke essen", "a": "halal", "e": "Abdullah ibn Dschafar berichtet, dass er den Propheten ﷺ frische Datteln zusammen mit Gurke essen sah. Eine einfache, gesunde Kombination.", "src": "Sahih al-Bukhari 5440 · Sahih Muslim 2043", "lv": 2, "d": "2026-11-16"},
  {"cat": "Alltag", "q": "Vor dem Schlafengehen eine brennende Kerze ausmachen", "a": "halal", "e": "Der Prophet ﷺ sagte: Lasst kein Feuer in euren Häusern brennen, wenn ihr schlafen geht. Ein Hadith, der bis heute vor Bränden schützt.", "src": "Sahih al-Bukhari 6293 · Sahih Muslim 2015", "lv": 2, "d": "2026-11-16"},
  {"cat": "Geld", "q": "Einem Freund mehr Zeit geben, weil er geliehenes Geld gerade nicht zurückzahlen kann", "a": "halal", "e": "Der Quran sagt: Wenn ein Schuldner in Schwierigkeiten ist, gebt ihm Aufschub, bis es ihm leichter fällt – und wer ihm die Schuld erlässt, tut noch Besseres.", "src": "Quran 2:280 mit Tafsir Ibn Kathir", "lv": 2, "d": "2026-11-16"},
  {"cat": "Gebet & Fasten", "q": "Ein verschlafenes Gebet nachholen, sobald man aufwacht", "a": "halal", "e": "Der Prophet ﷺ sagte: Wer ein Gebet vergisst oder verschläft, soll es beten, sobald er sich daran erinnert. Dafür gibt es keine andere Sühne.", "src": "Sahih al-Bukhari 597 · Sahih Muslim 684", "lv": 1, "d": "2026-11-16"},
  {"cat": "Gebet & Fasten", "q": "Während des Gebets nach links und rechts schauen", "a": "makruh", "e": "Aischa fragte den Propheten ﷺ nach dem Umherschauen im Gebet. Er antwortete, das sei ein Diebstahl, mit dem der Satan etwas vom Gebet eines Menschen wegnimmt. Man soll sich auf das Gebet konzentrieren.", "src": "Sahih al-Bukhari 751", "lv": 3, "d": "2026-11-16"},
  {"cat": "Miteinander", "q": "Einem Mitschüler helfen, der beim Lernen nicht mitkommt", "a": "halal", "e": "Der Prophet ﷺ sagte: Allah hilft Seinem Diener, solange der Diener seinem Bruder hilft. Und wer einen Weg geht, um Wissen zu suchen, dem macht Allah den Weg ins Paradies leicht.", "src": "Sahih Muslim 2699", "lv": 1, "d": "2026-11-18"},
  {"cat": "Miteinander", "q": "Auf Instagram mit teuren Sachen angeben, die man gar nicht besitzt", "a": "haram", "e": "Der Prophet ﷺ sagte: Wer vorgibt, etwas bekommen zu haben, das er nicht bekommen hat, ist wie jemand, der zwei Gewänder aus Lüge trägt. Einen falschen Eindruck zu erwecken, ist Täuschung.", "src": "Sahih al-Bukhari 5219 · Sahih Muslim 2130", "lv": 2, "d": "2026-11-18"},
  {"cat": "Alltag", "q": "Mit Freunden am Straßenrand abhängen", "a": "kommt", "e": "Der Prophet ﷺ riet, nicht an den Wegen zu sitzen. Als die Gefährten sagten, sie bräuchten diese Treffpunkte, erlaubte er es – wenn man dem Weg sein Recht gibt: den Blick senken, niemanden belästigen, den Gruß erwidern und zum Guten aufrufen.", "src": "Sahih al-Bukhari 2465 · Sahih Muslim 2121", "lv": 3, "d": "2026-11-18"},
  {"cat": "Essen", "q": "Kuhmilch trinken", "a": "halal", "e": "Der Quran nennt die Milch der Nutztiere ein Zeichen Allahs: rein und angenehm für die, die sie trinken.", "src": "Quran 16:66 mit Tafsir Ibn Kathir", "lv": 1, "d": "2026-11-18"},
  {"cat": "Essen", "q": "Fleisch essen, das bei der Schlachtung einem Götzen geweiht wurde", "a": "haram", "e": "Der Quran verbietet ausdrücklich Fleisch, über dem ein anderer Name als der Allahs genannt wurde, und was auf Opfersteinen für Götzen geschlachtet wurde.", "src": "Quran 2:173 mit Tafsir Ibn Kathir · Quran 5:3 mit Tafsir Ibn Kathir", "lv": 2, "d": "2026-11-18"},
  {"cat": "Essen", "q": "Fleisch essen, das Juden oder Christen geschlachtet haben", "a": "kommt", "e": "Der Quran erlaubt die Speise der Leute der Schrift. Die Gelehrten sind sich aber uneinig, ob heutige Schlachtungen diese Bedingungen erfüllen – manche erlauben das Fleisch, andere verlangen, dass richtig geschlachtet und Allahs Name genannt wurde.", "src": "Quran 5:5 mit Tafsir Ibn Kathir", "lv": 3, "d": "2026-11-18"},
  {"cat": "Alltag", "q": "Einem Tier ins Gesicht schlagen", "a": "haram", "e": "Jabir berichtet, dass der Prophet ﷺ verbot, Tiere ins Gesicht zu schlagen oder ihnen das Gesicht zu brandmarken.", "src": "Sahih Muslim 2116", "lv": 2, "d": "2026-11-18"},
  {"cat": "Alltag", "q": "Einen Obstbaum im Garten pflanzen", "a": "halal", "e": "Der Prophet ﷺ sagte: Wenn ein Muslim einen Baum pflanzt und dann ein Vogel, ein Mensch oder ein Tier davon isst, zählt das für ihn als Spende (Sadaqa).", "src": "Sahih al-Bukhari 2320 · Sahih Muslim 1553", "lv": 1, "d": "2026-11-18"},
  {"cat": "Gebet & Fasten", "q": "Ohne Wudu beten", "a": "haram", "e": "Der Quran schreibt vor dem Gebet die Gebetswaschung vor. Der Prophet ﷺ sagte: Das Gebet dessen, der unrein geworden ist, wird nicht angenommen, bis er Wudu macht.", "src": "Quran 5:6 mit Tafsir Ibn Kathir · Sahih al-Bukhari 135 · Sahih Muslim 225", "lv": 1, "d": "2026-11-18"},
  {"cat": "Gebet & Fasten", "q": "Im Ramadan das Fastenbrechen absichtlich hinauszögern, obwohl die Sonne schon untergegangen ist", "a": "makruh", "e": "Der Prophet ﷺ sagte: Den Menschen geht es gut, solange sie sich mit dem Fastenbrechen beeilen. Es ist Sunna, direkt nach Sonnenuntergang das Fasten zu brechen.", "src": "Sahih al-Bukhari 1957 · Sahih Muslim 1098", "lv": 2, "d": "2026-11-18"},
  {"cat": "Miteinander", "q": "Einen traurigen Mitschüler einfach freundlich anlächeln", "a": "halal", "e": "Der Prophet ﷺ sagte: Halte keine gute Tat für gering – auch nicht, deinem Bruder mit einem freundlichen Gesicht zu begegnen.", "src": "Sahih Muslim 2626", "lv": 1, "d": "2026-11-19"},
  {"cat": "Miteinander", "q": "Den kleinen Bruder liebevoll in den Arm nehmen und küssen", "a": "halal", "e": "Der Prophet ﷺ küsste seinen Enkel al-Hasan. Als ein Mann sagte, er habe seine zehn Kinder noch nie geküsst, antwortete der Prophet ﷺ: Wer nicht barmherzig ist, dem wird keine Barmherzigkeit erwiesen.", "src": "Sahih al-Bukhari 5997 · Sahih Muslim 2318", "lv": 1, "d": "2026-11-19"},
  {"cat": "Miteinander", "q": "Einen Freund zu einer Einladung mitbringen, zu der nur du eingeladen bist", "a": "kommt", "e": "Als dem Propheten ﷺ zu einer Einladung ein zusätzlicher Mann folgte, sagte er zum Gastgeber: Wenn du willst, lässt du ihn herein, und wenn du willst, schickst du ihn weg. Es kommt also darauf an, ob der Gastgeber einverstanden ist.", "src": "Sahih al-Bukhari 5434 · Sahih Muslim 2036", "lv": 3, "d": "2026-11-19"},
  {"cat": "Essen", "q": "Kamelfleisch essen", "a": "halal", "e": "Der Quran nennt die Opferkamele und sagt: Esst davon. Der Prophet ﷺ wurde gefragt, ob man nach Kamelfleisch die Gebetswaschung erneuern soll, und bejahte es – das Fleisch selbst war ganz selbstverständlich erlaubt.", "src": "Quran 22:36 mit Tafsir Ibn Kathir · Sahih Muslim 360", "lv": 1, "d": "2026-11-19"},
  {"cat": "Essen", "q": "Mit den Fingern statt mit Besteck essen", "a": "halal", "e": "Ka'b ibn Malik berichtet, dass der Prophet ﷺ mit drei Fingern aß und sie danach ableckte. Mit der Hand zu essen ist also Sunna – Besteck ist aber genauso erlaubt.", "src": "Sahih Muslim 2032", "lv": 2, "d": "2026-11-19"},
  {"cat": "Essen", "q": "Fleisch vom Wildesel essen", "a": "halal", "e": "Anders als der Hausesel ist der Wildesel erlaubt. Abu Qatada erlegte einen Wildesel, und als die Gefährten unsicher waren, sagte der Prophet ﷺ: Er ist erlaubt, esst ihn – und er aß selbst davon.", "src": "Sahih al-Bukhari 2570 · Sahih Muslim 1196", "lv": 3, "d": "2026-11-19"},
  {"cat": "Alltag", "q": "Sich nach der Toilette mit der rechten Hand sauber machen", "a": "makruh", "e": "Der Prophet ﷺ untersagte, sich auf der Toilette mit der rechten Hand zu reinigen – dafür nimmt man die linke. Die meisten Gelehrten halten es für makruh, wenn es ohne Grund geschieht.", "src": "Sahih al-Bukhari 153 · Sahih Muslim 267", "lv": 3, "d": "2026-11-19"},
  {"cat": "Alltag", "q": "Einen Gast, der bei dir übernachtet, großzügig bewirten", "a": "halal", "e": "Der Prophet ﷺ sagte: Wer an Allah und den Jüngsten Tag glaubt, soll seinen Gast ehren. Ein Gast hat ein Recht auf drei Tage Gastfreundschaft.", "src": "Sahih al-Bukhari 6019 · Sahih Muslim 48", "lv": 2, "d": "2026-11-19"},
  {"cat": "Gebet & Fasten", "q": "Sich vor dem Gebet mit dem Miswak die Zähne putzen", "a": "halal", "e": "Der Prophet ﷺ sagte: Wäre es nicht zu schwer für meine Gemeinschaft, hätte ich ihnen befohlen, vor jedem Gebet den Siwak zu benutzen. Zähneputzen vor dem Gebet ist deshalb eine empfohlene Sunna.", "src": "Sahih al-Bukhari 887 · Sahih Muslim 252", "lv": 2, "d": "2026-11-19"},
  {"cat": "Gebet & Fasten", "q": "Im Ramadan ohne Grund tagsüber absichtlich essen", "a": "haram", "e": "Das Fasten im Ramadan ist Pflicht für jeden gesunden, erwachsenen Muslim. Der Quran sagt: Esst und trinkt, bis sich die Morgendämmerung zeigt, dann vollendet das Fasten bis zur Nacht.", "src": "Quran 2:183 mit Tafsir Ibn Kathir · Quran 2:187 mit Tafsir Ibn Kathir", "lv": 1, "d": "2026-11-19"},
  {"cat": "Miteinander", "q": "Zwischen zwei zerstrittenen Freunden vermitteln, damit sie sich wieder vertragen", "a": "halal", "e": "Der Quran sagt: Die Gläubigen sind doch Brüder, so stiftet Frieden zwischen euren Brüdern. Streit schlichten ist deshalb nicht nur erlaubt, sondern eine gute Tat.", "src": "Quran 49:10 mit Tafsir Ibn Kathir", "lv": 1, "d": "2026-11-20"},
  {"cat": "Miteinander", "q": "Die geliehenen Kopfhörer eines Freundes einfach behalten", "a": "haram", "e": "Der Quran befiehlt, anvertraute Dinge ihren Besitzern zurückzugeben. Der Prophet ﷺ nannte es ein Zeichen des Heuchlers, wenn man ihm etwas anvertraut und er es nicht zurückgibt.", "src": "Quran 4:58 mit Tafsir Ibn Kathir · Sahih al-Bukhari 33", "lv": 1, "d": "2026-11-20"},
  {"cat": "Geld", "q": "Auf Social Media zeigen, wie viel man gespendet hat – nur damit alle einen loben", "a": "haram", "e": "Wer spendet, um von den Leuten gesehen zu werden, macht seine Spende zunichte, sagt der Quran. Der Prophet ﷺ warnte: Wer mit seinen guten Taten prahlt, um gelobt zu werden, dessen wahre Absicht macht Allah offenbar.", "src": "Quran 2:264 mit Tafsir Ibn Kathir · Sahih al-Bukhari 6499 · Sahih Muslim 2987", "lv": 3, "d": "2026-11-20"},
  {"cat": "Essen", "q": "Apfelessig im Salat essen", "a": "halal", "e": "Essig berauscht nicht und ist erlaubt. Der Prophet ﷺ aß Brot mit Essig und sagte: Was für eine gute Beilage ist Essig.", "src": "Sahih Muslim 2051, 2052", "lv": 1, "d": "2026-11-20"},
  {"cat": "Essen", "q": "Beim gemeinsamen Essen zwei Datteln auf einmal nehmen", "a": "kommt", "e": "Der Prophet ﷺ untersagte, beim gemeinsamen Essen zwei Datteln auf einmal zu nehmen – außer man hat die anderen um Erlaubnis gefragt. Mit Erlaubnis oder wenn man allein isst, ist es also in Ordnung.", "src": "Sahih al-Bukhari 2455 · Sahih Muslim 2045", "lv": 3, "d": "2026-11-20"},
  {"cat": "Essen", "q": "Beim Trinken in der Runde den Becher zuerst an den rechten Nachbarn weitergeben", "a": "halal", "e": "Als der Prophet ﷺ Milch getrunken hatte, gab er den Becher an den Mann zu seiner Rechten weiter und sagte: Erst der Rechte, dann wieder der Rechte. Das ist eine Sunna beim Teilen von Getränken.", "src": "Sahih al-Bukhari 5619 · Sahih Muslim 2029", "lv": 2, "d": "2026-11-20"},
  {"cat": "Alltag", "q": "Beim Betreten der eigenen Wohnung „Salam“ sagen", "a": "halal", "e": "Der Quran sagt: Wenn ihr Häuser betretet, so grüßt einander mit einem Gruß von Allah, gesegnet und gut. Auch wer nach Hause kommt, grüßt deshalb mit Salam.", "src": "Quran 24:61 mit Tafsir Ibn Kathir", "lv": 2, "d": "2026-11-20"},
  {"cat": "Alltag", "q": "Sich vor dem Einschlafen auf die rechte Seite legen und ein Dua sprechen", "a": "halal", "e": "Der Prophet ﷺ riet: Wenn du schlafen gehst, mach Wudu wie zum Gebet, leg dich auf die rechte Seite und sprich ein Bittgebet. Das ist eine empfohlene Sunna.", "src": "Sahih al-Bukhari 247 · Sahih Muslim 2710", "lv": 2, "d": "2026-11-20"},
  {"cat": "Gebet & Fasten", "q": "Nach dem Ramadan sechs Tage im Monat Schawwal freiwillig fasten", "a": "halal", "e": "Der Prophet ﷺ sagte: Wer im Ramadan fastet und danach sechs Tage im Schawwal, ist wie jemand, der das ganze Jahr gefastet hat. Diese Fastentage sind freiwillig und empfohlen.", "src": "Sahih Muslim 1164", "lv": 2, "d": "2026-11-20"},
  {"cat": "Gebet & Fasten", "q": "Beten, obwohl das Abendessen schon auf dem Tisch steht und man großen Hunger hat", "a": "makruh", "e": "Der Prophet ﷺ sagte: Wenn das Abendessen serviert ist und das Gebet beginnt, fangt mit dem Essen an. Wer hungrig betet, ist abgelenkt – die Gelehrten halten das für makruh, solange noch genug Zeit für das Gebet bleibt.", "src": "Sahih al-Bukhari 671, 672 · Sahih Muslim 557", "lv": 3, "d": "2026-11-20"},
  {"cat": "Miteinander", "q": "Einen Mitschüler, der dich beleidigt, nicht zurückbeleidigen, sondern ruhig bleiben", "a": "halal", "e": "Der Prophet ﷺ sagte: Wenn zwei sich beschimpfen, liegt die Sünde bei dem, der angefangen hat – solange der andere nicht übertreibt. Der Quran rät sogar: Wehre das Schlechte mit dem Besseren ab. Ruhig zu bleiben ist deshalb nicht nur erlaubt, sondern besonders gut.", "src": "Quran 41:34 mit Tafsir Ibn Kathir · Sahih Muslim 2587", "lv": 2, "d": "2026-11-21"},
  {"cat": "Alltag", "q": "Mit Freunden ein sportliches Wettrennen veranstalten", "a": "halal", "e": "Der Prophet ﷺ ließ selbst Wettrennen mit Pferden veranstalten, mit festen Start- und Zielpunkten. Sportliche Wettkämpfe sind deshalb erlaubt – solange kein Glücksspiel mit Geldeinsatz dabei ist.", "src": "Sahih al-Bukhari 2868 · Sahih Muslim 1870", "lv": 2, "d": "2026-11-21"},
  {"cat": "Miteinander", "q": "Einen Freund vor allen anderen übertrieben loben", "a": "makruh", "e": "Als jemand einen anderen in seiner Gegenwart übertrieben lobte, sagte der Prophet ﷺ: Du hast deinem Freund den Hals gebrochen. Wer lobt, soll maßvoll bleiben und sagen „Ich halte ihn für so und so“ – denn übertriebenes Lob kann eingebildet machen.", "src": "Sahih al-Bukhari 2662, 2663 · Sahih Muslim 3000", "lv": 3, "d": "2026-11-21"},
  {"cat": "Essen", "q": "Kürbis essen", "a": "halal", "e": "Kürbis ist ganz normales, erlaubtes Gemüse. Anas berichtet sogar, dass der Prophet ﷺ bei einem Essen gezielt die Kürbisstücke aus der Schüssel nahm – seitdem aß Anas selbst gern Kürbis.", "src": "Sahih al-Bukhari 5379 · Sahih Muslim 2041", "lv": 1, "d": "2026-11-21"},
  {"cat": "Essen", "q": "Nach dem Milchtrinken den Mund mit Wasser ausspülen", "a": "halal", "e": "Der Prophet ﷺ trank Milch, spülte danach den Mund aus und sagte: Sie hat Fett. Das Ausspülen ist deshalb eine schöne Sunna, besonders vor dem Gebet.", "src": "Sahih al-Bukhari 211 · Sahih Muslim 358", "lv": 3, "d": "2026-11-21"},
  {"cat": "Essen", "q": "Fleisch essen, bei dem der Schlachter absichtlich nicht „Bismillah“ gesagt hat", "a": "kommt", "e": "Der Quran sagt: Esst nicht von dem, worüber der Name Allahs nicht ausgesprochen wurde. Die Hanafiten, Malikiten und Hanbaliten halten solches Fleisch deshalb für haram, wenn der Name absichtlich weggelassen wurde. Die Schafiiten sehen das Aussprechen nur als Sunna an und erlauben das Fleisch.", "src": "Quran 6:121 mit Tafsir Ibn Kathir", "lv": 3, "d": "2026-11-21"},
  {"cat": "Alltag", "q": "Beim Betreten der Toilette ein Dua sprechen", "a": "halal", "e": "Wenn der Prophet ﷺ auf die Toilette ging, sagte er: O Allah, ich suche Zuflucht bei Dir vor dem Schlechten und den Schlechten. Dieses kurze Bittgebet vor dem Betreten ist eine empfohlene Sunna.", "src": "Sahih al-Bukhari 142 · Sahih Muslim 375", "lv": 2, "d": "2026-11-21"},
  {"cat": "Alltag", "q": "Mehr Wasser in die Suppe geben, um den Nachbarn etwas davon abzugeben", "a": "halal", "e": "Der Prophet ﷺ sagte zu Abu Dharr: Wenn du eine Brühe kochst, gib mehr Wasser dazu und denk an deine Nachbarn. Essen mit den Nachbarn zu teilen ist deshalb eine gute Tat.", "src": "Sahih Muslim 2625", "lv": 2, "d": "2026-11-21"},
  {"cat": "Gebet & Fasten", "q": "Den Gebetsruf (Adhan) leise mitsprechen, wenn man ihn hört", "a": "halal", "e": "Der Prophet ﷺ sagte: Wenn ihr den Adhan hört, dann sagt, was der Muezzin sagt. Das Nachsprechen ist eine empfohlene Sunna.", "src": "Sahih al-Bukhari 611 · Sahih Muslim 383", "lv": 1, "d": "2026-11-21"},
  {"cat": "Gebet & Fasten", "q": "Ein Pflichtgebet so hastig beten, dass man bei Verbeugung und Niederwerfung nicht kurz zur Ruhe kommt", "a": "haram", "e": "Ein Mann betete hastig, und der Prophet ﷺ sagte ihm dreimal: Geh zurück und bete, denn du hast nicht gebetet. Dann erklärte er ihm, in jeder Haltung zur Ruhe zu kommen. Die Gelehrten sehen diese Ruhe als Pflicht; ohne sie ist das Gebet mangelhaft oder ungültig.", "src": "Sahih al-Bukhari 757 · Sahih Muslim 397", "lv": 3, "d": "2026-11-21"},
  {"cat": "Miteinander", "q": "Auf einen Mitschüler herabschauen, weil seine Familie aus einem anderen Land kommt", "a": "haram", "e": "Der Quran sagt, dass Allah die Menschen zu Völkern und Stämmen gemacht hat, damit sie einander kennenlernen – und dass der Edelste der Gottesfürchtigste ist. Herkunft macht niemanden besser oder schlechter.", "src": "Quran 49:13 mit Tafsir Ibn Kathir", "lv": 1, "d": "2026-11-22"},
  {"cat": "Miteinander", "q": "Für einen Freund beim Lehrer falsch aussagen, damit er keinen Ärger bekommt", "a": "haram", "e": "Der Prophet ﷺ zählte das falsche Zeugnis zu den größten Sünden und warnte immer wieder davor. Der Quran fordert, für die Gerechtigkeit einzustehen, selbst gegen sich selbst oder die eigenen Leute.", "src": "Quran 4:135 mit Tafsir Ibn Kathir · Sahih al-Bukhari 2654 · Sahih Muslim 87", "lv": 2, "d": "2026-11-22"},
  {"cat": "Miteinander", "q": "Einen Freund im Streit „Kafir“ (Ungläubiger) nennen", "a": "haram", "e": "Der Prophet ﷺ sagte: Wer seinen Bruder „Ungläubiger“ nennt, bei dem trifft es einen von beiden. Einen Muslim so zu beschimpfen ist deshalb eine schwere Sünde.", "src": "Sahih al-Bukhari 6104 · Sahih Muslim 60", "lv": 2, "d": "2026-11-22"},
  {"cat": "Essen", "q": "Beim gemeinsamen Essen quer über die Platte greifen und von der Seite der anderen nehmen", "a": "makruh", "e": "Der Prophet ﷺ sagte zu einem Jungen, dessen Hand in der Schüssel umherwanderte: Sag Bismillah, iss mit der rechten Hand und iss von dem, was vor dir ist. Von der Seite der anderen zu nehmen ist deshalb unhöflich und verpönt.", "src": "Sahih al-Bukhari 5376 · Sahih Muslim 2022", "lv": 2, "d": "2026-11-22"},
  {"cat": "Essen", "q": "Sich am Buffet so vollstopfen, dass einem schlecht wird", "a": "makruh", "e": "Der Quran sagt: Esst und trinkt, aber seid nicht maßlos. Der Prophet ﷺ lobte, mit wenig zufrieden zu sein; die Gelehrten sehen übertriebenes Essen als verpönt, und wenn es der Gesundheit schadet, sogar als verboten.", "src": "Quran 7:31 mit Tafsir Ibn Kathir · Sahih al-Bukhari 5393 · Sahih Muslim 2060", "lv": 3, "d": "2026-11-22"},
  {"cat": "Essen", "q": "Direkt mit dem Mund aus der Öffnung eines großen gemeinsamen Wasserbehälters trinken", "a": "makruh", "e": "Der Prophet ﷺ verbot, direkt aus der Öffnung eines Wasserschlauchs zu trinken. Die Gelehrten sehen das als verpönt, vor allem aus Gründen der Sauberkeit und Rücksicht auf andere; besser trinkt man aus einem Becher.", "src": "Sahih al-Bukhari 5627, 5628", "lv": 3, "d": "2026-11-22"},
  {"cat": "Alltag", "q": "Einem Nachbarn helfen, seine schweren Einkaufstaschen zu tragen", "a": "halal", "e": "Der Prophet ﷺ sagte, dass es eine Sadaqa ist, jemandem beim Aufladen seines Gepäcks zu helfen. Solche kleinen Hilfen im Alltag sind gute Taten.", "src": "Sahih al-Bukhari 2989 · Sahih Muslim 1009", "lv": 1, "d": "2026-11-22"},
  {"cat": "Alltag", "q": "Vor dem Schlafengehen Gefäße mit Essen und Getränken abdecken", "a": "halal", "e": "Der Prophet ﷺ empfahl, abends die Türen zu schließen, die Wasserschläuche zuzubinden und die Gefäße abzudecken und dabei Allahs Namen zu erwähnen – notfalls mit einem quergelegten Stück Holz. Das ist eine empfohlene Sunna.", "src": "Sahih al-Bukhari 5623 · Sahih Muslim 2012", "lv": 3, "d": "2026-11-22"},
  {"cat": "Gebet & Fasten", "q": "Am Tag von Aschura (10. Muharram) freiwillig fasten", "a": "halal", "e": "Als der Prophet ﷺ nach Medina kam, fastete er am Tag von Aschura, an dem Allah Musa gerettet hatte, und forderte die Muslime ebenfalls dazu auf. Heute ist es ein empfohlenes freiwilliges Fasten.", "src": "Sahih al-Bukhari 2004 · Sahih Muslim 1130", "lv": 2, "d": "2026-11-22"},
  {"cat": "Gebet & Fasten", "q": "Das Witr-Gebet schon vor dem Schlafengehen beten", "a": "halal", "e": "Abu Huraira berichtete, der Prophet ﷺ habe ihm geraten, das Witr-Gebet vor dem Schlafen zu beten. Wer nicht sicher ist, ob er nachts aufwacht, betet es also besser schon vorher.", "src": "Sahih al-Bukhari 1981 · Sahih Muslim 721", "lv": 3, "d": "2026-11-22"},
  {"cat": "Miteinander", "q": "Für einen Freund Schmiere stehen, während er im Laden etwas klaut", "a": "haram", "e": "Der Quran sagt: Helft einander zur Güte und Gottesfurcht, aber nicht zur Sünde und Feindschaft. Wer beim Klauen hilft, macht bei der Sünde mit – auch wenn er selbst nichts nimmt.", "src": "Quran 5:2 mit Tafsir Ibn Kathir", "lv": 1, "d": "2026-11-23"},
  {"cat": "Miteinander", "q": "Einem Freund gönnen, dass er die bessere Note bekommen hat", "a": "halal", "e": "Der Prophet ﷺ sagte: Keiner von euch glaubt wirklich, bis er seinem Bruder wünscht, was er sich selbst wünscht. Anderen ihren Erfolg zu gönnen, ist deshalb ein Zeichen von echtem Glauben.", "src": "Sahih al-Bukhari 13 · Sahih Muslim 45", "lv": 1, "d": "2026-11-23"},
  {"cat": "Körper", "q": "Für ein Video eine gefährliche Mutprobe machen, bei der man sich schwer verletzen kann", "a": "haram", "e": "Der Quran sagt: Stürzt euch nicht mit eigener Hand ins Verderben, und: Tötet euch nicht selbst. Den eigenen Körper für Klicks ernsthaft in Gefahr zu bringen, ist deshalb nicht erlaubt.", "src": "Quran 2:195 mit Tafsir Ibn Kathir · Quran 4:29 mit Tafsir Ibn Kathir", "lv": 2, "d": "2026-11-23"},
  {"cat": "Essen", "q": "Fleisch von einem Tier essen, das von selbst gestorben ist", "a": "haram", "e": "Der Quran zählt verendete Tiere (Maita) ausdrücklich zu den verbotenen Speisen, zusammen mit Blut und Schweinefleisch. Fleisch ist nur halal, wenn das Tier richtig geschlachtet oder erjagt wurde.", "src": "Quran 5:3 mit Tafsir Ibn Kathir", "lv": 2, "d": "2026-11-23"},
  {"cat": "Essen", "q": "Einen Fisch essen, den das Meer tot an den Strand gespült hat", "a": "halal", "e": "Der Quran erlaubt die Beute und die Speise des Meeres. Als das Meer einen toten Wal an Land warf, aßen die Gefährten davon, und der Prophet ﷺ sagte: Esst, das ist Nahrung, die Allah euch gebracht hat – und aß selbst davon. Nur bei Fischen, die von selbst sterben und auf dem Wasser treiben, sind die Hanafiten strenger.", "src": "Quran 5:96 mit Tafsir Ibn Kathir · Sahih al-Bukhari 4362 · Sahih Muslim 1935", "lv": 3, "d": "2026-11-23"},
  {"cat": "Essen", "q": "Ein Glas Wasser in drei Zügen trinken und zwischendurch außerhalb des Glases atmen", "a": "halal", "e": "Der Prophet ﷺ trank in drei Zügen, atmete dazwischen außerhalb des Gefäßes und sagte: So stillt es den Durst besser und ist gesünder. Das ist eine schöne Sunna beim Trinken.", "src": "Sahih Muslim 2028", "lv": 2, "d": "2026-11-23"},
  {"cat": "Alltag", "q": "Nach dem Aufwachen die Hand in eine Schüssel mit Wasser tauchen, ohne sie vorher zu waschen", "a": "makruh", "e": "Der Prophet ﷺ sagte: Wer aus dem Schlaf aufwacht, soll seine Hand nicht ins Gefäß tauchen, bevor er sie gewaschen hat, denn er weiß nicht, wo seine Hand in der Nacht war. Die meisten Gelehrten sehen das als verpönt; Imam Ahmad hält das Waschen nach dem Nachtschlaf sogar für Pflicht.", "src": "Sahih al-Bukhari 162 · Sahih Muslim 278", "lv": 3, "d": "2026-11-23"},
  {"cat": "Körper", "q": "Die Achselhaare regelmäßig entfernen", "a": "halal", "e": "Der Prophet ﷺ zählte das Entfernen der Achselhaare zu den fünf Handlungen der Fitra, der natürlichen Reinheit – zusammen mit Nägelschneiden und Schnurrbartkürzen. Es ist deshalb eine empfohlene Sunna.", "src": "Sahih al-Bukhari 5891 · Sahih Muslim 257", "lv": 2, "d": "2026-11-23"},
  {"cat": "Gebet & Fasten", "q": "Ein Pflichtgebet zusammen mit anderen in der Gemeinschaft beten", "a": "halal", "e": "Der Prophet ﷺ sagte: Das Gebet in der Gemeinschaft ist siebenundzwanzigmal mehr wert als das Gebet allein. Wer kann, betet deshalb gern zusammen mit anderen.", "src": "Sahih al-Bukhari 645 · Sahih Muslim 650", "lv": 1, "d": "2026-11-23"},
  {"cat": "Gebet & Fasten", "q": "Am Montag freiwillig fasten", "a": "halal", "e": "Der Prophet ﷺ wurde nach dem Fasten am Montag gefragt und sagte: An diesem Tag wurde ich geboren, und an ihm wurde mir die Offenbarung herabgesandt. Das freiwillige Fasten am Montag ist deshalb eine empfohlene Sunna.", "src": "Sahih Muslim 1162", "lv": 2, "d": "2026-11-23"},
  {"cat": "Miteinander", "q": "Einen Mitschüler ohne Beweis verdächtigen, dass er dein Geld geklaut hat", "a": "haram", "e": "Der Quran sagt: Meidet viel Verdacht, denn mancher Verdacht ist Sünde. Der Prophet ﷺ sagte: Hütet euch vor Verdacht, denn Verdacht ist die lügenhafteste Rede.", "src": "Quran 49:12 mit Tafsir Ibn Kathir · Sahih al-Bukhari 6066 · Sahih Muslim 2563", "lv": 2, "d": "2026-11-24"},
  {"cat": "Miteinander", "q": "Einem Freund, der dich um Rat fragt, ehrlich deine Meinung sagen", "a": "halal", "e": "Der Prophet ﷺ sagte: Die Religion ist aufrichtiger Rat (Nasiha) – auch gegenüber den Muslimen. Wer um Rat gefragt wird, soll ehrlich und wohlwollend antworten.", "src": "Sahih Muslim 55", "lv": 2, "d": "2026-11-24"},
  {"cat": "Miteinander", "q": "Sich bewusst Freunde aussuchen, die einen guten Einfluss haben", "a": "halal", "e": "Der Prophet ﷺ verglich einen guten Freund mit einem Moschusverkäufer, von dem man immer etwas Wohlriechendes mitnimmt, und einen schlechten mit einem Schmied, dessen Blasebalg einem die Kleidung versengt. Gute Freunde zu wählen ist deshalb sehr empfohlen.", "src": "Sahih al-Bukhari 5534 · Sahih Muslim 2628", "lv": 1, "d": "2026-11-24"},
  {"cat": "Geld", "q": "Einem Mitschüler ein Angebot wegschnappen, über das er sich mit dem Verkäufer gerade einig wird", "a": "haram", "e": "Der Prophet ﷺ sagte: Keiner von euch soll seinen Bruder überbieten oder in einen Handel eingreifen, den dieser gerade abschließt. Das gilt auch für Kleinanzeigen und Online-Verkäufe.", "src": "Sahih al-Bukhari 2139 · Sahih Muslim 1412", "lv": 3, "d": "2026-11-24"},
  {"cat": "Essen", "q": "Hühnchen essen", "a": "halal", "e": "Abu Musa berichtet: Ich sah den Propheten ﷺ Hühnchen essen. Hühnerfleisch ist halal, wenn das Tier richtig geschlachtet wurde.", "src": "Sahih al-Bukhari 5517", "lv": 1, "d": "2026-11-24"},
  {"cat": "Essen", "q": "Nach dem Essen „Alhamdulillah“ sagen", "a": "halal", "e": "Der Prophet ﷺ sagte: Allah ist zufrieden mit Seinem Diener, der einen Bissen isst oder einen Schluck trinkt und Ihn dafür lobt. Dank nach dem Essen ist eine schöne Sunna.", "src": "Sahih Muslim 2734", "lv": 1, "d": "2026-11-24"},
  {"cat": "Essen", "q": "Beim Schlachten das Messer vorher gut schärfen, damit das Tier nicht unnötig leidet", "a": "halal", "e": "Der Prophet ﷺ sagte: Allah hat Güte in allem vorgeschrieben – wenn ihr schlachtet, dann schlachtet auf gute Weise. Jeder soll sein Messer schärfen und dem Tier Erleichterung verschaffen.", "src": "Sahih Muslim 1955", "lv": 2, "d": "2026-11-24"},
  {"cat": "Alltag", "q": "Nach dem Isha-Gebet noch bis spät in die Nacht ohne Grund mit Freunden chatten", "a": "makruh", "e": "Abu Barza berichtet, dass der Prophet ﷺ es nicht mochte, vor dem Isha-Gebet zu schlafen und danach noch zu plaudern. Die Gelehrten halten nutzloses Gerede nach Isha deshalb für makruh – für Wichtiges oder Gutes ist es erlaubt.", "src": "Sahih al-Bukhari 568 · Sahih Muslim 647", "lv": 3, "d": "2026-11-24"},
  {"cat": "Gebet & Fasten", "q": "Am Freitag vor dem Freitagsgebet duschen (Ghusl machen)", "a": "halal", "e": "Der Prophet ﷺ sagte: Wer von euch zum Freitagsgebet kommt, soll vorher die Ganzkörperwaschung (Ghusl) machen. Die meisten Gelehrten sehen sie als stark empfohlene Sunna, einige sogar als Pflicht.", "src": "Sahih al-Bukhari 877 · Sahih Muslim 844", "lv": 2, "d": "2026-11-24"},
  {"cat": "Gebet & Fasten", "q": "Beim Gebet ein kleines Kind auf dem Arm tragen", "a": "halal", "e": "Abu Qatada berichtet, dass der Prophet ﷺ betete und dabei seine kleine Enkelin Umama trug: Beim Niederwerfen setzte er sie ab, beim Aufstehen nahm er sie wieder hoch. Wenn es nötig ist, macht das das Gebet nicht ungültig.", "src": "Sahih al-Bukhari 516 · Sahih Muslim 543", "lv": 3, "d": "2026-11-24"},
  {"cat": "Miteinander", "q": "Einem Freund verzeihen, der dich verletzt hat", "a": "halal", "e": "Der Quran fordert dazu auf, zu verzeihen und nachsichtig zu sein: „Wollt ihr nicht, dass Allah euch vergibt?“ Ibn Kathir erklärt, dass der Vers herabkam, als Abu Bakr einem Verwandten, der ihn schwer gekränkt hatte, seine Unterstützung entziehen wollte – und ihm dann doch verzieh.", "src": "Quran 24:22 mit Tafsir Ibn Kathir", "lv": 1, "d": "2026-11-25"},
  {"cat": "Miteinander", "q": "Im Streit die Mutter eines Mitschülers beleidigen", "a": "haram", "e": "Der Prophet ﷺ sagte: Zu den größten Sünden gehört es, die eigenen Eltern zu beschimpfen – nämlich, indem man die Eltern eines anderen beschimpft und dieser dann die eigenen Eltern zurückbeschimpft.", "src": "Sahih al-Bukhari 5973 · Sahih Muslim 90", "lv": 2, "d": "2026-11-25"},
  {"cat": "Miteinander", "q": "In der Mensa einen Mitschüler von seinem Platz aufstehen lassen, um sich selbst dorthin zu setzen", "a": "haram", "e": "Der Prophet ﷺ verbot, jemanden von seinem Platz aufstehen zu lassen, um sich selbst dorthin zu setzen. Stattdessen soll man sagen: Rückt zusammen und macht Platz. Die meisten Gelehrten verstehen das als Verbot.", "src": "Sahih al-Bukhari 6269 · Sahih Muslim 2177", "lv": 3, "d": "2026-11-25"},
  {"cat": "Essen", "q": "Brot mit Olivenöl essen", "a": "halal", "e": "Der Quran erwähnt einen Baum, der am Berg Sinai wächst und Öl und Würze für die Essenden hervorbringt. Ibn Kathir erklärt, dass damit der Olivenbaum gemeint ist.", "src": "Quran 23:20 mit Tafsir Ibn Kathir", "lv": 1, "d": "2026-11-25"},
  {"cat": "Essen", "q": "Trüffel essen", "a": "halal", "e": "Der Prophet ﷺ sagte: Trüffel sind eine Art Manna (sie wachsen ohne Zutun des Menschen), und ihr Saft ist ein Heilmittel für die Augen.", "src": "Sahih al-Bukhari 5708 · Sahih Muslim 2049", "lv": 2, "d": "2026-11-25"},
  {"cat": "Essen", "q": "Haifisch essen", "a": "halal", "e": "Der Quran erlaubt, was aus dem Meer gefangen wird. Der Hai ist ein Fisch – deshalb gilt er bei allen vier Rechtsschulen als halal, auch bei den Hanafiten, die von den Meerestieren nur Fische erlauben.", "src": "Quran 5:96 mit Tafsir Ibn Kathir", "lv": 2, "d": "2026-11-25"},
  {"cat": "Miteinander", "q": "Als Gast so lange bleiben, dass es für den Gastgeber zur Last wird", "a": "haram", "e": "Der Prophet ﷺ sagte: Die Bewirtung eines Gastes dauert drei Tage, was darüber hinausgeht, ist Sadaqa. Und es ist dem Gast nicht erlaubt, so lange zu bleiben, dass er seinen Gastgeber in Bedrängnis bringt.", "src": "Sahih al-Bukhari 6135 · Sahih Muslim 48", "lv": 3, "d": "2026-11-25"},
  {"cat": "Alltag", "q": "Mit nur einem Schuh herumlaufen", "a": "makruh", "e": "Der Prophet ﷺ sagte: Keiner von euch soll mit nur einem Schuh gehen – entweder trägt er beide oder keinen. Die meisten Gelehrten halten es für makruh.", "src": "Sahih al-Bukhari 5856 · Sahih Muslim 2097", "lv": 3, "d": "2026-11-25"},
  {"cat": "Gebet & Fasten", "q": "In den letzten zehn Nächten des Ramadan nach der Nacht der Bestimmung (Laylat al-Qadr) suchen", "a": "halal", "e": "Der Quran sagt, dass die Nacht der Bestimmung besser ist als tausend Monate. Der Prophet ﷺ sagte: Sucht sie in den letzten zehn Nächten des Ramadan.", "src": "Quran 97:3 mit Tafsir Ibn Kathir · Sahih al-Bukhari 2017 · Sahih Muslim 1169", "lv": 1, "d": "2026-11-25"},
  {"cat": "Gebet & Fasten", "q": "Kinder zur Übung fasten lassen, obwohl sie noch nicht dazu verpflichtet sind", "a": "halal", "e": "Rubayyi' bint Mu'awwidh berichtet, dass die Gefährten am Tag von Aschura auch ihre Kinder fasten ließen und ihnen Spielzeug aus Wolle gaben, damit sie bis zum Fastenbrechen durchhielten. Zum Üben ist das gut – überfordern soll man Kinder aber nicht.", "src": "Sahih al-Bukhari 1960 · Sahih Muslim 1136", "lv": 3, "d": "2026-11-25"},
  {"cat": "Miteinander", "q": "Als Junge einem Freund zur Begrüßung die Hand geben", "a": "halal", "e": "Qatada fragte Anas, ob es unter den Gefährten des Propheten ﷺ üblich war, sich die Hand zu geben – Anas sagte: Ja. Der Handschlag unter Freunden ist also eine schöne, alte Gewohnheit.", "src": "Sahih al-Bukhari 6263", "lv": 1, "d": "2026-11-26"},
  {"cat": "Miteinander", "q": "Einem Freund etwas Gutes über den Islam weitererzählen, das man gerade gelernt hat", "a": "halal", "e": "Der Prophet ﷺ sagte: Gebt von mir weiter, und sei es nur ein Vers. Im selben Hadith warnt er aber davor, ihm absichtlich etwas Falsches zuzuschreiben – erzähl also nur weiter, was du sicher weißt.", "src": "Sahih al-Bukhari 3461", "lv": 1, "d": "2026-11-26"},
  {"cat": "Alltag", "q": "Bei Geld und Aussehen auch auf die schauen, denen es schlechter geht als dir", "a": "halal", "e": "Der Prophet ﷺ sagte: Wenn einer von euch jemanden sieht, der mehr Besitz hat oder besser aussieht, soll er auch auf den schauen, der weniger hat. So unterschätzt man nicht, was Allah einem geschenkt hat – ein guter Tipp gegen Neid beim Scrollen durch Social Media.", "src": "Sahih al-Bukhari 6490 · Sahih Muslim 2963", "lv": 2, "d": "2026-11-26"},
  {"cat": "Geld", "q": "Beim Verkauf auf Kleinanzeigen ständig schwören, dass die Ware super ist – auch wenn es stimmt", "a": "makruh", "e": "Der Prophet ﷺ sagte: Hütet euch vor vielem Schwören beim Verkaufen – es bringt die Ware zwar schnell an den Mann, nimmt aber den Segen weg. Deshalb halten die Gelehrten häufiges Schwören beim Handel für makruh; wer dabei lügt, begeht sogar eine schwere Sünde.", "src": "Sahih al-Bukhari 2087 · Sahih Muslim 1607", "lv": 3, "d": "2026-11-26"},
  {"cat": "Alltag", "q": "Heimlich durch das Fenster in die Wohnung der Nachbarn schauen", "a": "haram", "e": "Ein Mann spähte durch ein Loch in das Haus des Propheten ﷺ. Der Prophet ﷺ tadelte ihn scharf und erklärte: Die Bitte um Erlaubnis vor dem Eintreten wurde gerade wegen der Blicke vorgeschrieben. Die Privatsphäre anderer ist also geschützt.", "src": "Sahih al-Bukhari 6241 · Sahih Muslim 2156", "lv": 2, "d": "2026-11-26"},
  {"cat": "Essen", "q": "Zamzam-Wasser trinken", "a": "halal", "e": "Abu Dharr lebte in Mekka etwa einen Monat lang nur von Zamzam-Wasser. Der Prophet ﷺ sagte darüber: Es ist gesegnet, und es dient auch als Nahrung.", "src": "Sahih Muslim 2473", "lv": 2, "d": "2026-11-26"},
  {"cat": "Essen", "q": "Aus dem Kochtopf der nicht-muslimischen Nachbarn essen, in dem auch Schweinefleisch gekocht wird", "a": "kommt", "e": "Abu Tha'laba fragte, ob sie aus dem Geschirr der Leute der Schrift essen dürfen. Der Prophet ﷺ sagte: Wenn ihr anderes Geschirr findet, esst nicht daraus; wenn nicht, wascht es und esst daraus. Am besten nimmst du also eigenes Geschirr – geht das nicht, muss der Topf vorher gründlich gewaschen werden.", "src": "Sahih al-Bukhari 5478 · Sahih Muslim 1930", "lv": 3, "d": "2026-11-26"},
  {"cat": "Essen", "q": "Morgens Ajwa-Datteln essen", "a": "halal", "e": "Der Prophet ﷺ sagte: Wer jeden Morgen sieben Ajwa-Datteln isst, dem schaden an diesem Tag weder Gift noch Zauberei. Ajwa ist eine Dattelsorte aus Medina.", "src": "Sahih al-Bukhari 5445 · Sahih Muslim 2047", "lv": 2, "d": "2026-11-26"},
  {"cat": "Gebet & Fasten", "q": "Beim Betreten der Moschee zwei Rak'as beten, bevor man sich hinsetzt", "a": "halal", "e": "Der Prophet ﷺ sagte: Wenn einer von euch die Moschee betritt, soll er zwei Rak'as beten, bevor er sich setzt. Die meisten Gelehrten sehen dieses Gebet (Tahiyyat al-Masjid) als stark empfohlene Sunna, nicht als Pflicht.", "src": "Sahih al-Bukhari 444 · Sahih Muslim 714", "lv": 2, "d": "2026-11-26"},
  {"cat": "Gebet & Fasten", "q": "Im Ramadan fasten, aber dabei weiter lügen und lästern", "a": "haram", "e": "Lügen und Lästern sind immer verboten – beim Fasten wiegt es besonders schwer. Der Prophet ﷺ sagte: Wer falsche Rede und schlechtes Handeln nicht lässt, bei dem hat Allah kein Bedürfnis danach, dass er sein Essen und Trinken lässt. Das Fasten wird dadurch nach den meisten Gelehrten nicht ungültig, verliert aber seinen Lohn.", "src": "Sahih al-Bukhari 1903", "lv": 2, "d": "2026-11-26"},
  {"cat": "Alltag", "q": "Die ganze Freizeit nur mit Zocken und Scrollen auf dem Handy verbringen", "a": "kommt", "e": "Spielen und Scrollen sind an sich nicht verboten. Der Prophet ﷺ warnte aber: Bei zwei Gaben lassen sich viele Menschen täuschen – bei der Gesundheit und der freien Zeit. Wer darüber Gebete verpasst oder seine Pflichten vernachlässigt, macht daraus etwas Verbotenes.", "src": "Sahih al-Bukhari 6412", "lv": 2, "d": "2026-11-27"},
  {"cat": "Alltag", "q": "An eine Sünde denken, sie dann aber doch nicht tun", "a": "halal", "e": "Der Prophet ﷺ berichtete von seinem Herrn: Wer etwas Schlechtes vorhat und es dann doch nicht tut, dem schreibt Allah sogar eine volle gute Tat gut. Ein schlechter Gedanke allein ist also keine Sünde – entscheidend ist, dass man sich dagegen entscheidet.", "src": "Sahih al-Bukhari 6491 · Sahih Muslim 131", "lv": 3, "d": "2026-11-27"},
  {"cat": "Miteinander", "q": "Einen Freund einladen, mit dir zusammen zum Gebet zu gehen", "a": "halal", "e": "Der Prophet ﷺ sagte: Wer zu etwas Gutem anleitet, bekommt denselben Lohn wie der, der es tut. Wer einen Freund freundlich zum Gebet mitnimmt, bekommt also selbst auch Lohn dafür.", "src": "Sahih Muslim 1893", "lv": 1, "d": "2026-11-27"},
  {"cat": "Essen", "q": "Beim Essen bequem zurückgelehnt sitzen", "a": "makruh", "e": "Der Prophet ﷺ sagte: Ich esse nicht angelehnt. Viele Gelehrte halten es deshalb für makruh, beim Essen angelehnt oder halb liegend zu sitzen – besser ist es, aufrecht zu sitzen.", "src": "Sahih al-Bukhari 5398", "lv": 3, "d": "2026-11-27"},
  {"cat": "Essen", "q": "Ein Wildtier essen, das mit einem Stock totgeschlagen wurde", "a": "haram", "e": "Der Quran verbietet das Fleisch von Tieren, die erschlagen wurden. Der Prophet ﷺ erklärte zur Jagd: Trifft die scharfe Spitze das Tier, darf man es essen – wird es mit der breiten Seite erschlagen, ist es verboten.", "src": "Quran 5:3 mit Tafsir Ibn Kathir · Sahih al-Bukhari 5475", "lv": 3, "d": "2026-11-27"},
  {"cat": "Essen", "q": "Süßigkeiten essen", "a": "halal", "e": "Aischa berichtete, dass der Prophet ﷺ Süßes und Honig mochte. Süßigkeiten sind also erlaubt – solange keine verbotenen Zutaten wie Schweinegelatine oder Alkohol drin sind und man es nicht übertreibt.", "src": "Sahih al-Bukhari 5431 · Sahih Muslim 1474", "lv": 1, "d": "2026-11-27"},
  {"cat": "Gebet & Fasten", "q": "Nach dem Pflichtgebet je 33-mal „Subhanallah“, „Alhamdulillah“ und „Allahu Akbar“ sagen", "a": "halal", "e": "Der Prophet ﷺ empfahl, nach jedem Pflichtgebet je 33-mal Subhanallah, Alhamdulillah und Allahu Akbar zu sagen. Das ist eine empfohlene Sunna, keine Pflicht – und es dauert nur ein, zwei Minuten.", "src": "Sahih al-Bukhari 843 · Sahih Muslim 597", "lv": 2, "d": "2026-11-27"},
  {"cat": "Gebet & Fasten", "q": "Bei großer Hitze das Mittagsgebet (Dhuhr) etwas später beten", "a": "halal", "e": "Der Prophet ﷺ sagte: Wenn es sehr heiß ist, betet das Dhuhr-Gebet, wenn es etwas kühler geworden ist. Man darf es also ein wenig verschieben – aber nur innerhalb der Gebetszeit.", "src": "Sahih al-Bukhari 533 · Sahih Muslim 615", "lv": 3, "d": "2026-11-27"},
  {"cat": "Miteinander", "q": "Als Jüngerer einen älteren Menschen zuerst grüßen", "a": "halal", "e": "Der Prophet ﷺ sagte: Der Jüngere grüßt den Älteren, der Vorbeigehende den Sitzenden und die kleine Gruppe die große. Wer jünger ist, macht also den ersten Schritt.", "src": "Sahih al-Bukhari 6231", "lv": 2, "d": "2026-11-27"},
  {"cat": "Alltag", "q": "Bei Plänen für morgen „Inshallah“ sagen", "a": "halal", "e": "Der Quran sagt: Sag nie von etwas: „Ich werde das morgen tun“ – ohne hinzuzufügen: „wenn Allah will“. Ibn Kathir erklärt, dass man so alles, was man vorhat, auf Allahs Willen zurückführt.", "src": "Quran 18:23–24 mit Tafsir Ibn Kathir", "lv": 1, "d": "2026-11-27"},
];
